// cc -O2 mandelbrot.c -o mandelbrot_c
#include <stdio.h>
#include <stdint.h>

static int64_t mandel_iter(double cr, double ci, int64_t max_iter) {
    double zr = 0.0, zi = 0.0;
    for (int64_t i = 0; i < max_iter; i++) {
        double zr2 = zr * zr;
        double zi2 = zi * zi;
        if (zr2 + zi2 > 4.0) return i;
        double new_zr = zr2 - zi2 + cr;
        double new_zi = 2.0 * zr * zi + ci;
        zr = new_zr;
        zi = new_zi;
    }
    return max_iter;
}

int main(void) {
    int64_t width = 1000, height = 1000, max_iter = 1000;
    int64_t checksum = 0;
    for (int64_t y = 0; y < height; y++) {
        for (int64_t x = 0; x < width; x++) {
            double cr = -2.0 + 3.0 * (double)x / (double)width;
            double ci = -1.5 + 3.0 * (double)y / (double)height;
            checksum += mandel_iter(cr, ci, max_iter);
        }
    }
    printf("mandelbrot checksum = %lld\n", (long long)checksum);
    return 0;
}

// cc -O2 matmul.c -o matmul_c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

int main(void) {
    const int n = 512;
    int64_t *a = malloc(sizeof(int64_t) * n * n);
    int64_t *b = malloc(sizeof(int64_t) * n * n);
    int64_t *c = malloc(sizeof(int64_t) * n * n);
    for (int i = 0; i < n * n; i++) {
        a[i] = ((int64_t)i * 3) % 7;
        b[i] = ((int64_t)i * 5) % 11;
        c[i] = 0;
    }
    for (int row = 0; row < n; row++) {
        for (int col = 0; col < n; col++) {
            int64_t sum = 0;
            for (int k = 0; k < n; k++) {
                sum += a[row * n + k] * b[k * n + col];
            }
            c[row * n + col] = sum;
        }
    }
    int64_t checksum = 0;
    for (int i = 0; i < n * n; i++) checksum += c[i];
    printf("matmul(512) checksum = %lld\n", (long long)checksum);
    free(a); free(b); free(c);
    return 0;
}

// cc -O2 nbody.c -o nbody_c -lm
#include <stdio.h>
#include <stdint.h>
#include <math.h>

int main(void) {
    const int n = 5;
    const int64_t steps = 2000000;
    const double dt = 0.01;

    double x[5]  = {0.0, 1.0, 2.0, 3.0, 4.0};
    double y[5]  = {0.0, 0.5, 1.0, 1.5, 2.0};
    double z[5]  = {0,0,0,0,0};
    double vx[5] = {0,0,0,0,0};
    double vy[5] = {0,0,0,0,0};
    double vz[5] = {0,0,0,0,0};
    double mass[5] = {1.0, 0.5, 0.5, 0.3, 0.2};

    for (int64_t s = 0; s < steps; s++) {
        for (int i = 0; i < n; i++) {
            double fx = 0, fy = 0, fz = 0;
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    double dx = x[j] - x[i];
                    double dy = y[j] - y[i];
                    double dz = z[j] - z[i];
                    double r2 = dx*dx + dy*dy + dz*dz + 0.001;
                    double r  = sqrt(r2);
                    double inv_r3 = mass[j] / (r2 * r);
                    fx += dx * inv_r3;
                    fy += dy * inv_r3;
                    fz += dz * inv_r3;
                }
            }
            vx[i] += fx * dt;
            vy[i] += fy * dt;
            vz[i] += fz * dt;
        }
        for (int k = 0; k < n; k++) {
            x[k] += vx[k] * dt;
            y[k] += vy[k] * dt;
            z[k] += vz[k] * dt;
        }
    }

    double checksum = 0;
    for (int k = 0; k < n; k++) checksum += x[k] + y[k] + z[k];
    printf("nbody checksum (rounded) = %lld\n", (long long)checksum);
    return 0;
}

