fn collect_callees(inst: &Instruction, out: &mut Vec<String>) {

/// The subset of `module` whose functions are reachable from `main` (module
/// with no `main` is passed through untouched). Emitting only this subset
/// keeps an unsupported construct in an UNCALLED stdlib/module function from
/// failing the whole build.
fn reachable_subset(module: &MirModule) -> MirModule {

    // All string-bearing primitives use the packed-i64 convention
    // (low 32 = byte offset, high 32 = byte length) consistent with
    // kryos_string_concat. Array primitives use the same scheme.
    // ====================================================================

    // string_length(packed) -> i32
    self.types.ty().function(vec![ValType::I64], vec![ValType::I32]);
    self.imports.import(env_module, "kryos_string_length",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_length_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // string_slice(packed, start, end) -> packed
    self.types.ty().function(
        vec![ValType::I64, ValType::I32, ValType::I32],
        vec![ValType::I64],
    );
    self.imports.import(env_module, "kryos_string_slice",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_slice_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // string_to_upper(packed) -> packed
    self.types.ty().function(vec![ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_string_to_upper",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_to_upper_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // string_to_lower(packed) -> packed
    self.types.ty().function(vec![ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_string_to_lower",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_to_lower_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // string_trim(packed) -> packed
    self.types.ty().function(vec![ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_string_trim",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_trim_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // string_index_of(packed_haystack, packed_needle) -> i32 (-1 if absent)
    self.types.ty().function(
        vec![ValType::I64, ValType::I64],
        vec![ValType::I32],
    );
    self.imports.import(env_module, "kryos_string_index_of",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_index_of_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // string_parse_int(packed) -> i64
    self.types.ty().function(vec![ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_string_parse_int",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_parse_int_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // string_parse_float(packed) -> f64
    self.types.ty().function(vec![ValType::I64], vec![ValType::F64]);
    self.imports.import(env_module, "kryos_string_parse_float",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_parse_float_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // array_length(packed) -> i32
    self.types.ty().function(vec![ValType::I64], vec![ValType::I32]);
    self.imports.import(env_module, "kryos_array_length",
        wasm_encoder::EntityType::Function(self.type_count));
    self.array_length_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // array_push(packed, value) -> packed (new handle, since growth may reallocate)
    self.types.ty().function(
        vec![ValType::I64, ValType::I64],
        vec![ValType::I64],
    );
    self.imports.import(env_module, "kryos_array_push",
        wasm_encoder::EntityType::Function(self.type_count));
    self.array_push_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // array_pop(packed) -> i64 (-1 sentinel when empty)
    self.types.ty().function(vec![ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_array_pop",
        wasm_encoder::EntityType::Function(self.type_count));
    self.array_pop_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // json_parse(packed_str) -> handle_i64
    self.types.ty().function(vec![ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_json_parse",
        wasm_encoder::EntityType::Function(self.type_count));
    self.json_parse_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // json_stringify(handle) -> packed_str
    self.types.ty().function(vec![ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_json_stringify",
        wasm_encoder::EntityType::Function(self.type_count));
    self.json_stringify_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // json_get_int(handle, key_off, key_len) -> i64
    self.types.ty().function(
        vec![ValType::I64, ValType::I32, ValType::I32],
        vec![ValType::I64],
    );
    self.imports.import(env_module, "kryos_json_get_int",
        wasm_encoder::EntityType::Function(self.type_count));
    self.json_get_int_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // json_get_str(handle, key_off, key_len) -> packed_str
    self.types.ty().function(
        vec![ValType::I64, ValType::I32, ValType::I32],
        vec![ValType::I64],
    );
    self.imports.import(env_module, "kryos_json_get_str",
        wasm_encoder::EntityType::Function(self.type_count));
    self.json_get_str_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // regex_test(packed_pat, packed_subject) -> i32 (0/1)
    self.types.ty().function(
        vec![ValType::I64, ValType::I64],
        vec![ValType::I32],
    );
    self.imports.import(env_module, "kryos_regex_test",
        wasm_encoder::EntityType::Function(self.type_count));
    self.regex_test_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // regex_replace(packed_pat, packed_subject, packed_repl) -> packed
    self.types.ty().function(
        vec![ValType::I64, ValType::I64, ValType::I64],
        vec![ValType::I64],
    );
    self.imports.import(env_module, "kryos_regex_replace",
        wasm_encoder::EntityType::Function(self.type_count));
    self.regex_replace_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // http_fetch(method_off,len, url_off,len, body_off,len) -> packed_response
    self.types.ty().function(
        vec![
            ValType::I32, ValType::I32,
            ValType::I32, ValType::I32,
            ValType::I32, ValType::I32,
        ],
        vec![ValType::I64],
    );
    self.imports.import(env_module, "kryos_http_fetch",
        wasm_encoder::EntityType::Function(self.type_count));
    self.http_fetch_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // to_string_i64(v: i64) -> packed_str  — decimal formatting of an i64
    self.types.ty().function(vec![ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_to_string_i64",
        wasm_encoder::EntityType::Function(self.type_count));
    self.to_string_i64_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // to_string_f64(v: f64) -> packed_str  — decimal formatting of an f64
    self.types.ty().function(vec![ValType::F64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_to_string_f64",
        wasm_encoder::EntityType::Function(self.type_count));
    self.to_string_f64_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // string_char_at(packed: i64, idx: i64) -> packed_str  — single-char substring at idx
    self.types.ty().function(vec![ValType::I64, ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_string_char_at",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_char_at_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // string_retain(packed: i64) -> i64  — ARC retain; no-op in WASM (returns same handle)
    self.types.ty().function(vec![ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_string_retain",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_retain_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // string_char_code(packed: i64) -> i64  — byte value of first char
    self.types.ty().function(vec![ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_string_char_code",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_char_code_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // string_contains(haystack: i64, needle: i64) -> i64  — 1 if needle found in haystack
    self.types.ty().function(vec![ValType::I64, ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_string_contains",
        wasm_encoder::EntityType::Function(self.type_count));
    self.string_contains_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // ---- Maps (host-backed, like arrays). Keys are packed strings, values
    // i64. The host keeps a JS Map per handle. map_new() -> handle. ----
    // map_new() -> i64 handle
    self.types.ty().function(vec![], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_map_new",
        wasm_encoder::EntityType::Function(self.type_count));
    self.map_new_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // map_insert_str(handle, key_packed, value) -> i64 (handle passthrough)
    self.types.ty().function(vec![ValType::I64, ValType::I64, ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_map_insert_str",
        wasm_encoder::EntityType::Function(self.type_count));
    self.map_insert_str_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // map_get_str(handle, key_packed) -> i64 (value, 0 if absent)
    self.types.ty().function(vec![ValType::I64, ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_map_get_str",
        wasm_encoder::EntityType::Function(self.type_count));
    self.map_get_str_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // map_has_str(handle, key_packed) -> i64 (1/0)
    self.types.ty().function(vec![ValType::I64, ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_map_has_str",
        wasm_encoder::EntityType::Function(self.type_count));
    self.map_has_str_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // map_len(handle) -> i32
    self.types.ty().function(vec![ValType::I64], vec![ValType::I32]);
    self.imports.import(env_module, "kryos_map_len",
        wasm_encoder::EntityType::Function(self.type_count));
    self.map_len_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // ---- Integer-keyed map variants. MIR lowers map<i64, V> through
    // kryos_map_insert/get/has (the native runtime names); before these
    // imports existed, any int-keyed map program failed the wasm build. ----
    // map_insert(handle, key_i64, value) -> i64 (handle passthrough; the
    // native fn is void but MIR assigns the call result to a temp, so the
    // wasm import must produce a value)
    self.types.ty().function(vec![ValType::I64, ValType::I64, ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_map_insert",
        wasm_encoder::EntityType::Function(self.type_count));
    self.map_insert_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // map_get(handle, key_i64) -> i64 (value, 0 if absent)
    self.types.ty().function(vec![ValType::I64, ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_map_get",
        wasm_encoder::EntityType::Function(self.type_count));
    self.map_get_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;

    // map_has(handle, key_i64) -> i64 (1/0)
    self.types.ty().function(vec![ValType::I64, ValType::I64], vec![ValType::I64]);
    self.imports.import(env_module, "kryos_map_has",
        wasm_encoder::EntityType::Function(self.type_count));
    self.map_has_idx = self.func_count;
    self.func_count += 1; self.type_count += 1;
}

/// Synthesize a thunk MirFunction per lambda used as a closure. The thunk
/// `__wasm_thunk_<lambda>(env: i64, user_args...) -> ret` reads the lambda's
/// captures from the env array (`array_get(env, i+1)`) and forwards them
/// plus the user args to the real lambda. This gives every closure a
/// UNIFORM indirect-call ABI: the closure value is an env array
/// `[thunk_idx, cap0, ...]`, and `call_indirect` always calls the thunk.
fn build_closure_thunks(&mut self, module: &MirModule) -> Result<(), WasmCodegenError> {
    // Collect closured lambda name -> capture count.
    let mut closured: HashMap<String, usize> = HashMap::new();
    for func in &module.functions {
        for block in &func.blocks {
            for inst in &block.instructions {
                if let Instruction::Assign {
                    value: RValue::Closure { func_name, captures },
                    ..
                } = inst
                {
                    closured.insert(func_name.clone(), captures.len());
                }
            }
        }
    }
    // Deterministic order (thunks get stable indices).
    let mut names: Vec<_> = closured.into_iter().collect();
    names.sort();

    for (lambda_name, num_caps) in names {
        let lambda = module
            .functions
            .iter()
            .find(|f| f.name == lambda_name)
            .ok_or_else(|| {
                WasmCodegenError::unsupported(&format!(
                    "closure over unknown function `{lambda_name}`"
                ))

            })?;
        // f64/f32 captures would need a bitcast from the i64 array slot we
        // don't emit here; keep the honest error for that rare case.
        for p in lambda.params.iter().take(num_caps) {
            if matches!(p.ty, MirType::F64 | MirType::F32) {
                return Err(WasmCodegenError::unsupported(
                    "wasm closure capturing an f64/f32 value (capture i64/str/handle \
                     values, or use --backend cranelift/llvm)",
                ));
            }
        }
        let user_params: Vec<MirParam> = lambda.params.iter().skip(num_caps).cloned().collect();
        let ret = lambda.ret_ty.clone();

        let mut locals: Vec<MirLocal> = Vec::new();
        let mut next: u32 = 0;
        // env is local 0.
        let env = LocalId(next);
        locals.push(MirLocal { id: env, name: Some("__env".into()), ty: MirType::I64, mutable: false });
        next += 1;
        // user params are locals 1..=M (wasm param convention: params first).
        let mut user_locals: Vec<(LocalId, MirType)> = Vec::new();
        for (i, up) in user_params.iter().enumerate() {
            let id = LocalId(next);
            locals.push(MirLocal { id, name: Some(format!("__u{i}")), ty: up.ty.clone(), mutable: false });
            next += 1;
            user_locals.push((id, up.ty.clone()));
        }
        // capture temps.
        let mut cap_locals: Vec<LocalId> = Vec::new();
        for i in 0..num_caps {
            let id = LocalId(next);
            locals.push(MirLocal { id, name: Some(format!("__c{i}")), ty: lambda.params[i].ty.clone(), mutable: false });
            next += 1;
            cap_locals.push(id);
        }

        let mut instrs: Vec<Instruction> = Vec::new();
        for (i, &cid) in cap_locals.iter().enumerate() {
            instrs.push(Instruction::Assign {
                dest: cid,
                value: RValue::Call {
                    func: "array_get".into(),
                    args: vec![
                        Operand::Local(env),
                        Operand::Constant(Constant::Int((i + 1) as i64)),
                    ],
                },
            });
        }
        // call real lambda(caps..., users...).
        let mut call_args: Vec<Operand> =
            cap_locals.iter().map(|&c| Operand::Local(c)).collect();
        for (uid, _) in &user_locals {
            call_args.push(Operand::Local(*uid));
        }
        let terminator = if is_void(&ret) {
            // void return: call for side effect, into a void sink local.
            let sink = LocalId(next);
            locals.push(MirLocal { id: sink, name: Some("__sink".into()), ty: MirType::Void, mutable: false });
            let _ = next; // sink was the final local
            instrs.push(Instruction::Assign {
                dest: sink,
                value: RValue::Call { func: lambda_name.clone(), args: call_args },
            });
            Terminator::Return(None)
        } else {
            let result = LocalId(next);
            locals.push(MirLocal { id: result, name: Some("__r".into()), ty: ret.clone(), mutable: false });
            #[allow(unused_assignments)]
            { next += 1; }
            instrs.push(Instruction::Assign {
                dest: result,
                value: RValue::Call { func: lambda_name.clone(), args: call_args },
            });
            Terminator::Return(Some(Operand::Local(result)))
        };

        let mut params = vec![MirParam { local: env, ty: MirType::I64 }];
        for (uid, uty) in &user_locals {
            params.push(MirParam { local: *uid, ty: uty.clone() });
        }
        self.synth_thunks.push(MirFunction {
            name: format!("__wasm_thunk_{lambda_name}"),
            params,
            ret_ty: ret,
            blocks: vec![BasicBlock { id: BlockId(0), instructions: instrs, terminator }],
            locals,
            attributes: MirAttributes::default(),
            source_file: None,
            source_line: 0,
        });
    }
    Ok(())
}

/// Walk the module once to assign function indices and signature indices.
fn plan_functions(&mut self, module: &MirModule) -> Result<(), WasmCodegenError> {
    for func in &module.functions {
        // Build the WASM function signature from the MIR parameter and
        // return types.
        let mut params = Vec::with_capacity(func.params.len());
        for p in &func.params {
            params.push(lower_type(&p.ty)?);
        }
        let results: Vec<ValType> = if is_void(&func.ret_ty) {
            self.void_user_fns.insert(func.name.clone());
            vec![]
        } else {
            vec![lower_type(&func.ret_ty)?]
        };

        let sig_idx = self.type_count;
        self.types.ty().function(params, results);
        self.type_count += 1;

        self.funcs.function(sig_idx);
        let fn_idx = self.func_count;
        self.func_count += 1;

        self.fn_indices.insert(func.name.clone(), fn_idx);
        self.fn_sigs.insert(func.name.clone(), sig_idx);

        // Export every function so the host can call any of them (handy
        // for testing and library usage).
        self.exports
            .export(&func.name, ExportKind::Func, fn_idx);
    }
    // Plan the synthesized closure thunks (take out to avoid the self
    // borrow, plan each, restore for emission). Record thunk index per
    // lambda so the Closure rvalue can put it in env[0].
    let thunks = std::mem::take(&mut self.synth_thunks);
    for thunk in &thunks {
        let mut params = Vec::with_capacity(thunk.params.len());
        for p in &thunk.params {
            params.push(lower_type(&p.ty)?);
        }
        let results: Vec<ValType> = if is_void(&thunk.ret_ty) {
            self.void_user_fns.insert(thunk.name.clone());
            vec![]
        } else {
            vec![lower_type(&thunk.ret_ty)?]
        };
        let sig_idx = self.type_count;
        self.types.ty().function(params, results);
        self.type_count += 1;
        self.funcs.function(sig_idx);
        let fn_idx = self.func_count;
        self.func_count += 1;
        self.fn_indices.insert(thunk.name.clone(), fn_idx);
        self.fn_sigs.insert(thunk.name.clone(), sig_idx);
        if let Some(lambda) = thunk.name.strip_prefix("__wasm_thunk_") {
            self.closure_thunk_idx.insert(lambda.to_string(), fn_idx);
        }
    }
    self.synth_thunks = thunks;
    Ok(())
}

/// Emit the body of one function.
fn emit_function(&mut self, func: &MirFunction) -> Result<(), WasmCodegenError> {
    // Lower every local to a WASM val type so we can declare them up front.
    // Locals 0..params.len() are reserved for parameters by WASM convention.
    let n_params = func.params.len();
    let mut local_decls: Vec<(u32, ValType)> = Vec::new();

    // Group consecutive same-type locals to keep the function header small.
    let mut current_group: Option<(ValType, u32)> = None;
    for local in func.locals.iter().skip(n_params) {
        // Map every MIR local to *some* WASM val type so local indices
        // stay aligned. Void locals get i32 as a placeholder; we never
        // read or write them (see Assign / Drop handling).
        let vt = if is_void(&local.ty) {
            ValType::I32
        } else {
            match lower_type(&local.ty) {
                Ok(t) => t,
                Err(_) => {
                    // Unsupported local type — for v0.1 we lower it to i64
                    // as a placeholder. Any actual use will fail later,
                    // but unused locals stay harmless.
                    ValType::I64
                }
            }
        };
        match current_group {
            Some((t, count)) if t == vt => current_group = Some((t, count + 1)),
            Some((t, count)) => {
                local_decls.push((count, t));
                current_group = Some((vt, 1));
            }
            None => current_group = Some((vt, 1)),
        }
    }
    if let Some((t, count)) = current_group {
        local_decls.push((count, t));
    }

    // v0.2: reserve THREE extra i64 scratch locals at the very end of every
    // function. func.locals.len() = `cg_scratch_local` (string unpack,
    // array/map/env building); +1 = `cg_scratch_local2` (closure env across
    // call_indirect arg emission); +2 = `cg_pc_local` (the dispatch
    // relooper's program counter, which must survive across block bodies).
    match local_decls.last_mut() {
        Some(entry) if entry.1 == ValType::I64 => entry.0 += 3,
        _ => local_decls.push((3, ValType::I64)),
    }

    // Try the structured-control-flow translator first (it produces small,
    // idiomatic wasm for the common shapes). If it can't express the CFG
    // (nested loops, irreducible edges), fall back to the dispatch relooper
    // which handles ANY reducible CFG. The structured attempt writes into a
    // throwaway `Function`; on error we discard it and re-emit. CG-level
    // state touched during the attempt (string interning) is dedup-safe.
    let mut wfunc = Function::new(local_decls.clone());
    let structured = self.emit_function_body(func, &mut wfunc);
    if structured.is_err() {
        wfunc = Function::new(local_decls);
        self.emit_function_body_relooper(func, &mut wfunc)?;
    }

    // Every wasm function body must terminate with `end`. If the last
    // emitted terminator fell through (no Return/Unreachable), push a
    // default return value for non-void functions so validation passes.
    if !is_void(&func.ret_ty) {
        match lower_type(&func.ret_ty) {
            Ok(ValType::I32) => {
                wfunc.instruction(&W::I32Const(0));
            }
            Ok(ValType::I64) => {
                wfunc.instruction(&W::I64Const(0));
            }
            Ok(ValType::F32) => {
                wfunc.instruction(&W::F32Const(0.0));
            }
            Ok(ValType::F64) => {
                wfunc.instruction(&W::F64Const(0.0));
            }
            _ => {}
        }
    }
    wfunc.instruction(&W::End);

    self.code.function(&wfunc);
    Ok(())
}

/// Emit a function body using a structured-control-flow strategy.
///
/// We support the common shapes the Kryos front-end emits:
///
/// 1. **Straight-line** — one or more blocks chained via `Goto`/`Return`.
/// 2. **If/else (including chained elif)** — nested `Branch` arms that
///    eventually `Goto` a common join block.
/// 3. **While loop** — header block ends in `Branch { cond, body, exit }`,
///    body ends in `Goto(header)`.
///
/// More complex CFGs (irreducible loops, multi-entry blocks, exception
/// handling) return an unsupported error.
fn emit_function_body(
    &mut self,
    func: &MirFunction,
    wfunc: &mut Function,
) -> Result<(), WasmCodegenError> {
    let n_params = func.params.len();

    // Map `BlockId.0` (the *identifier*, not the array index) to the
    // index in `func.blocks`. MIR block ids are non-contiguous: the
    // front-end may skip numbers when blocks are pruned.
    let mut id_to_index: HashMap<u32, usize> = HashMap::new();
    for (i, b) in func.blocks.iter().enumerate() {
        id_to_index.insert(b.id.0, i);
    }

    let visited = vec![false; func.blocks.len()];
    let mut emitter = FnEmitter {
        cg: self,
        func,
        wfunc,
        n_params,
        id_to_index,
        visited,
    };
    // The entry block is always the first one in `func.blocks` (the
    // Cranelift backend relies on the same convention).
    let entry_id = func.blocks[0].id;
    emitter.emit_block(entry_id)?;
    Ok(())
}

/// Emit a function body as a DISPATCH RELOOPER: one `loop` whose body is an
/// if-else chain over a program-counter local. This expresses ANY reducible
/// CFG (nested loops, multi-exit blocks) that the structured translator
/// can't, at the cost of a per-edge dispatch. Used only as a fallback when
/// `emit_function_body` returns an error, so structured functions are
/// unaffected. All inter-block values already live in wasm locals (MIR is
/// register-based), so nothing needs to survive on the operand stack.
fn emit_function_body_relooper(
    &mut self,
    func: &MirFunction,

        wfunc: &mut Function,
    ) -> Result<(), WasmCodegenError> {
        let n_params = func.params.len();
        let mut id_to_index: HashMap<u32, usize> = HashMap::new();
        for (i, b) in func.blocks.iter().enumerate() {
            id_to_index.insert(b.id.0, i);
        }
        let visited = vec![false; func.blocks.len()];
        let mut emitter = FnEmitter {
            cg: self,
            func,
            wfunc,
            n_params,
            id_to_index,
            visited,
        };
        emitter.emit_relooper()
    }

    /// Allocate (or return cached) string literal in the data segment.
    /// Returns (offset, length_in_bytes).
    fn intern_string(&mut self, s: &str) -> (u32, u32) {
        if let Some(&pair) = self.string_table.get(s) {
            return pair;
        }
        let bytes = s.as_bytes();
        let offset = self.string_cursor;
        let len = bytes.len() as u32;
        self.string_bytes.extend_from_slice(bytes);
        self.string_cursor += len;
        // Align to 4 for cleanliness.
        while self.string_cursor % 4 != 0 {
            self.string_bytes.push(0);
            self.string_cursor += 1;
        }
        self.string_table.insert(s.to_string(), (offset, len));
        (offset, len)
    }

    /// Register (or reuse) a function type for `call_indirect` and return its
    /// type index. Deduped by a canonical string key so repeated closure
    /// signatures share one type entry.
    fn indirect_type_index(&mut self, params: &[ValType], ret: Option<ValType>) -> u32 {
        let key = format!("{params:?}->{ret:?}");
        if let Some(&idx) = self.indirect_types.get(&key) {
            return idx;
        }
        let idx = self.type_count;
        let results: Vec<ValType> = ret.into_iter().collect();
        self.types.ty().function(params.to_vec(), results);
        self.type_count += 1;
        self.indirect_types.insert(key, idx);
        idx
    }

    /// Finalize: stitch all sections together into the final module bytes.
    fn finish(self) -> Vec<u8> {
        let mut m = Module::new();
        m.section(&self.types);
        m.section(&self.imports);
        m.section(&self.funcs);
        // Table of all functions (index i -> function i) so closures can be
        // called via `call_indirect`. A closure value is a function's table
        // index; the element segment below makes every function ref-able.
        let mut table = TableSection::new();
        table.table(TableType {
            element_type: RefType::FUNCREF,
            minimum: self.func_count as u64,
            maximum: Some(self.func_count as u64),
            table64: false,
            shared: false,
        });
        m.section(&table);
        m.section(&self.memory);
        m.section(&self.exports);
        // Active element segment: table[i] = function i for every function.
        let all_fns: Vec<u32> = (0..self.func_count).collect();
        let mut elems = ElementSection::new();
        elems.active(
            None,
            &ConstExpr::i32_const(0),
            Elements::Functions(all_fns.into()),
        );
        m.section(&elems);
        m.section(&self.code);
        if !self.string_bytes.is_empty() {
            m.section(&self.data);
        }
        m.finish()
    }
}

// ---------------------------------------------------------------------------
// Per-function emitter — owns a mutable borrow of the codegen state plus the
// wasm-encoder `Function` builder.
// ---------------------------------------------------------------------------

/// ```text
/// loop {
///   <cond>
///   br_if exit_label
///   <body>
///   br loop_label
/// }
/// <continuation: exit block>
/// ```
fn emit_simple_while(
    &mut self,
    header: BlockId,
    cond: &Operand,
    body: BlockId,
    exit: BlockId,
) -> Result<(), WasmCodegenError> {
    // Mark the body as visited (we'll inline it inside the loop), and let
    // the header's "already visited" check prevent recursion when the body
    // does Goto(header).
    let body_idx = self.block_index(body)?;
    if self.visited[body_idx] {
        return Err(WasmCodegenError::unsupported(
            "loop body already visited (irreducible CFG)",
        ));
    }

    self.wfunc.instruction(&W::Block(BlockType::Empty));
    self.wfunc.instruction(&W::Loop(BlockType::Empty));

    // FIRST: re-run the header block's instructions (they compute the
    // loop condition on each iteration).
    let header_idx = self.block_index(header)?;
    for inst in self.func.blocks[header_idx].instructions.clone() {
        self.emit_instruction(&inst)?;
    }

    // Then evaluate the condition + branch out if false.
    // Kryos booleans are i64 (0 = false, anything else = true).
    // WASM's `i32.eqz` / `br_if` work on i32, so wrap.
    self.emit_operand(cond)?;
    self.wfunc.instruction(&W::I32WrapI64);
    self.wfunc.instruction(&W::I32Eqz);
    self.wfunc.instruction(&W::BrIf(1)); // break out of outer block

    // Body: emit body block's instructions, ignoring its Goto(header)
    // terminator (we replace it with `br 0` to loop back).
    self.visited[body_idx] = true;
    let body_block = &self.func.blocks[body_idx];
    for inst in &body_block.instructions {
        self.emit_instruction(inst)?;
    }
    // body should terminate in Goto(header) — that's the loop edge.
    // Also handle Switch (while-true with inner match, e.g. `while let`).
    match body_block.terminator.clone() {
        Terminator::Goto(b) if b == header => {
            self.wfunc.instruction(&W::Br(0)); // continue
        }
        // for-range: body -> increment block(s) -> header. Emit each
        // intermediate block's instructions (e.g. `i = i + 1`) inline,
        // then loop back.
        Terminator::Goto(next) => {
            let mut cur = next;
            let mut guard = 0;
            loop {
                if cur == header {
                    self.wfunc.instruction(&W::Br(0));
                    break;
                }
                let cidx = self.block_index(cur)?;
                if self.visited[cidx] {
                    return Err(WasmCodegenError::unsupported(
                        "loop increment chain already visited (irreducible CFG)",
                    ));
                }
                self.visited[cidx] = true;
                for inst in self.func.blocks[cidx].instructions.clone() {
                    self.emit_instruction(&inst)?;
                }
                match self.func.blocks[cidx].terminator.clone() {
                    Terminator::Goto(nb) => cur = nb,
                    _ => {
                        return Err(WasmCodegenError::unsupported(
                            "loop increment chain must be straight Goto",
                        ))
                    }
                }
                guard += 1;
                if guard > 64 {
                    return Err(WasmCodegenError::unsupported("loop increment chain too long"));
                }
            }
        }
        Terminator::Return(value) => {
            // Early return inside loop body.
            if let Some(op) = &value {
                self.emit_operand(op)?;
            }
            self.wfunc.instruction(&W::Return);
        }
        Terminator::Switch { value, targets, default } => {
            // `while true { match expr { Pat => body, _ => break } }` pattern.
            // We're inside: block(outer) { loop { ... [body instrs] [here] } }
            // Emit each matching arm as an `if`; arm back-edge = br 1 (loop),
            // fall-through default = br 1 (outer block = exit).
            self.emit_while_body_switch(&value, &targets, default, header, exit)?;
        }
        Terminator::Branch { cond: inner_cond, then_block, else_block } => {
            // `while cond { if inner { A } B; i++ }` pattern.
            // The body ends in an inner Branch; one arm is short (Return or back-edge),
            // the other is the through path to the loop header.
            self.emit_while_body_inner_branch(&inner_cond, then_block, else_block, header)?;
        }
        _ => {
            return Err(WasmCodegenError::unsupported(
                "while-loop body must end in Goto(header) or Return",
            ));
        }
    }

    self.wfunc.instruction(&W::End); // end loop
    self.wfunc.instruction(&W::End); // end outer block

    // Continue with the exit block.
    self.emit_block(exit)?;
    Ok(())
}

/// Emit an "inverted while" where the THEN arm exits and the ELSE arm loops back.
///
/// Pattern produced by tail-call optimisation on recursive functions:
///   `if exit_cond { return base }  // then_block (exit)`
///   `// else: body that Goto(header) // else_block chain`
///
/// WASM structure:
///   block(outer)     ; br 1 = exit
///     loop           ; br 0 = continue
///       [header instrs]
///       [exit_cond]
///       i32.wrap_i64
///       br_if 1      ; exit when cond is true
///       [else_block body chain]
///       br 0         ; continue
///     end loop
///   end block
///   [then_block = exit continuation]
fn emit_inverted_while(
    &mut self,
    header: BlockId,
    cond: &Operand,
    then_block: BlockId,
    else_block: BlockId,
) -> Result<(), WasmCodegenError> {
    let body_idx = self.block_index(else_block)?;
    if self.visited[body_idx] {
        return Err(WasmCodegenError::unsupported(
            "inverted-while body already visited (irreducible CFG)",
        ));
    }

    self.wfunc.instruction(&W::Block(BlockType::Empty));
    self.wfunc.instruction(&W::Loop(BlockType::Empty));

    let header_idx = self.block_index(header)?;
    for inst in self.func.blocks[header_idx].instructions.clone() {
        self.emit_instruction(&inst)?;
    }

    // Exit when the condition is true (no negation — contrast with emit_simple_while).
    self.emit_operand(cond)?;
    self.wfunc.instruction(&W::I32WrapI64);
    self.wfunc.instruction(&W::BrIf(1));

    // Body: follow the else_block chain until Goto(header) or Return.
    let mut current_body = else_block;
    loop {
        let curr_idx = self.block_index(current_body)?;
        if self.visited[curr_idx] {
            return Err(WasmCodegenError::unsupported("inverted-while body block already visited"));
        }
        self.visited[curr_idx] = true;
        let instrs = self.func.blocks[curr_idx].instructions.clone();
        for inst in &instrs {
            self.emit_instruction(inst)?;
        }
        let term = self.func.blocks[curr_idx].terminator.clone();
        match term {
            Terminator::Goto(b) if b == header => {
                self.wfunc.instruction(&W::Br(0));
                break;
            }
            Terminator::Goto(next) => {
                current_body = next;
            }
            Terminator::Return(value) => {
                if let Some(op) = &value {
                    self.emit_operand(op)?;
                }
                self.wfunc.instruction(&W::Return);
                break;
            }
            _ => {
                return Err(WasmCodegenError::unsupported(
                    "inverted-while body must end in Goto(header) or Return",
                ));
            }
        }
    }

    self.wfunc.instruction(&W::End); // end loop
    self.wfunc.instruction(&W::End); // end outer block

    self.emit_block(then_block)?;
    Ok(())
}

/// Emit the body of a `while true { match expr { Pat => ..., _ => break } }` loop.
///
/// Called from `emit_simple_while` when the body block terminates in a Switch.
/// We are already inside:
///   block(outer)  ; br 1 from loop body = exit
///     loop        ; br 0 from loop body = continue
///       [header instructions already emitted]
///       [condition check already emitted]
///       [body_bb instructions already emitted]
///       [we are HERE — body terminated in Switch]
///
/// For each matching arm we emit `if (tag == val) { arm_instrs; br 1 } end`
/// where inside the if: br 0 exits the if, br 1 continues the loop, br 2 exits.
/// After all ifs, we emit `br 1` (exit outer block = break the loop).
fn emit_while_body_switch(
    &mut self,
    value: &Operand,
    targets: &[(i64, BlockId)],
    default: BlockId,
    loop_header: BlockId,
    loop_exit: BlockId,
) -> Result<(), WasmCodegenError> {
    // Group targets by arm block (or-patterns share one block).
    let mut seen_bids: Vec<u32> = Vec::new();
    let mut bid_vals: HashMap<u32, (BlockId, Vec<i64>)> = HashMap::new();
    for (val, bid) in targets {
        if let Some(entry) = bid_vals.get_mut(&bid.0) {
            entry.1.push(*val);
        } else {
            seen_bids.push(bid.0);
            bid_vals.insert(bid.0, (*bid, vec![*val]));
        }
    }

    // Emit one `if` per unique arm.
    for &bid_u32 in &seen_bids {
        let (bid, vals) = &bid_vals[&bid_u32];
        self.emit_switch_cond(value, vals)?;
        self.wfunc.instruction(&W::If(BlockType::Empty));
        // Inside the if: depth 0=if, 1=loop, 2=outer block.

        let arm_idx = self.block_index(*bid)?;
        if !self.visited[arm_idx] {
            self.visited[arm_idx] = true;
            let instrs: Vec<_> = self.func.blocks[arm_idx].instructions.clone();
            for inst in &instrs {
                self.emit_instruction(inst)?;
            }
            let arm_term = self.func.blocks[arm_idx].terminator.clone();
            match arm_term {
                Terminator::Goto(b) if b == loop_header => {
                    self.wfunc.instruction(&W::Br(1)); // continue loop
                }
                Terminator::Goto(b) if b == loop_exit => {
                    self.wfunc.instruction(&W::Br(2)); // exit loop
                }
                Terminator::Goto(b) if self.goto_chain_reaches(b, loop_header) => {
                    // Multi-block arm that eventually loops back; inline chain.
                    let mut cur = b;
                    loop {
                        let ci = self.block_index(cur)?;
                        if self.visited[ci] {
                            self.wfunc.instruction(&W::Br(1));
                            break;
                        }
                        self.visited[ci] = true;
                        let ci_instrs: Vec<_> = self.func.blocks[ci].instructions.clone();
                        for inst in &ci_instrs { self.emit_instruction(inst)?; }
                        match self.func.blocks[ci].terminator.clone() {
                            Terminator::Goto(n) if n == loop_header => {
                                self.wfunc.instruction(&W::Br(1)); // continue
                                break;
                            }
                            Terminator::Goto(n) => { cur = n; }
                            Terminator::Return(ref v) => {
                                if let Some(op) = v.as_ref() { self.emit_operand(op)?; }
                                self.wfunc.instruction(&W::Return);
                                break;
                            }
                            // A Branch/Switch inside the arm chain (e.g.
                            // `while let` with an `if`/`match` in the loop
                            // body) is beyond this fast path. It MUST fail
                            // the structured attempt so the dispatch
                            // relooper takes over -- emitting a silent
                            // W::Unreachable here compiled cleanly and then

                            // TRAPPED at runtime mid-loop.
                            _ => {
                                return Err(WasmCodegenError::unsupported(
                                    "switch-while arm with nested branch; relooper fallback",
                                ));
                            }
                        }
                    }
                }
                Terminator::Return(ref v) => {
                    if let Some(op) = v.as_ref() { self.emit_operand(op)?; }
                    self.wfunc.instruction(&W::Return);
                }
                // Same contract as above: unexpressible arm shape -> error
                // out to the relooper, never a silent runtime trap.
                _ => {
                    return Err(WasmCodegenError::unsupported(
                        "switch-while arm terminator; relooper fallback",
                    ));
                }
            }
        }
        self.wfunc.instruction(&W::End); // end if
    }

    // Default arm (break/fallthrough): mark visited, emit its instructions.
    let default_idx = self.block_index(default)?;
    if !self.visited[default_idx] {
        self.visited[default_idx] = true;
        let def_instrs: Vec<_> = self.func.blocks[default_idx].instructions.clone();
        for inst in &def_instrs { self.emit_instruction(inst)?; }
        // Terminator of default is typically Goto(loop_exit) = break.
        // We DON'T emit it; the `br 1` below handles the exit.
    }

    // Fall-through after all ifs = no arm matched = break the loop.
    // At body depth (inside loop, outside any if): br 1 = exit outer block.
    self.wfunc.instruction(&W::Br(1));

    Ok(())
}

/// Emit `while cond { if inner { A } B; i++ }` — an inner Branch inside a while-loop body.
///
/// We are already inside:
///   block(outer)  ; br 1 = exit loop
///     loop        ; br 0 = continue loop
///       [header instrs + exit check done]
///       [body instrs done]
///       [HERE: body terminated in Branch(inner_cond, then_block, else_block)]
///
/// Strategy: one arm is "short" (ends in Return or loops back to header),
/// the other is the "through" arm (merge path that eventually reaches header).
/// Emit: if [cond] { short_arm } through_arm_chain; br 0
fn emit_while_body_inner_branch(
    &mut self,
    cond: &Operand,
    then_block: BlockId,
    else_block: BlockId,
    loop_header: BlockId,
) -> Result<(), WasmCodegenError> {
    // Fast path: diamond join pattern — both arms directly Goto the same non-header block.
    // Emits: if { then_exclusive } [else { else_exclusive }] join_chain; br 0
    // This avoids the then-arm swallowing the shared join block and starving the else path.
    let diamond_join: Option<BlockId> = {
        let ti = self.id_to_index.get(&then_block.0).copied();
        let ei = self.id_to_index.get(&else_block.0).copied();
        match (ti, ei) {
            (Some(ti), Some(ei)) => {
                match (&self.func.blocks[ti].terminator, &self.func.blocks[ei].terminator) {
                    (Terminator::Goto(j1), Terminator::Goto(j2))
                        if j1 == j2 && *j1 != loop_header => Some(*j1),
                    _ => None,
                }
            }
            _ => None,
        }
    };
    if let Some(join) = diamond_join {
        self.emit_operand(cond)?;
        self.wfunc.instruction(&W::I32WrapI64);
        self.wfunc.instruction(&W::If(BlockType::Empty));
        self.emit_arm(then_block, Some(join))?;
        if else_block != join {
            self.wfunc.instruction(&W::Else);
            self.emit_arm(else_block, Some(join))?;
        }
        self.wfunc.instruction(&W::End);
        // Emit join chain until loop_header or Return, then br 0 (continue).
        let mut current = join;
        loop {
            let curr_idx = self.block_index(current)?;
            if self.visited[curr_idx] {
                self.wfunc.instruction(&W::Br(0));
                return Ok(());
            }
            self.visited[curr_idx] = true;
            let instrs = self.func.blocks[curr_idx].instructions.clone();
            for inst in &instrs { self.emit_instruction(inst)?; }
            match self.func.blocks[curr_idx].terminator.clone() {
                Terminator::Goto(b) if b == loop_header => {
                    self.wfunc.instruction(&W::Br(0));
                    return Ok(());
                }
                Terminator::Goto(next) => { current = next; }
                Terminator::Return(val) => {
                    if let Some(op) = &val { self.emit_operand(op)?; }
                    self.wfunc.instruction(&W::Return);
                    return Ok(());
                }
                _ => {
                    self.wfunc.instruction(&W::Br(0));
                    return Ok(());
                }
            }
        }
    }

    let then_has_return = self.chain_has_return(then_block);
    let else_has_return = self.chain_has_return(else_block);
    let then_reaches_else = self.goto_chain_reaches(then_block, else_block);
    let then_reaches_header = self.goto_chain_reaches(then_block, loop_header);
    let else_reaches_header = self.goto_chain_reaches(else_block, loop_header);

    // Both arms loop back to the header (e.g. a `continue`) without a simple
    // diamond join (handled above). The visited-based emission below would
    // place the shared increment block in only ONE arm, so the other arm
    // would skip it (wrong / infinite loop). Defer to the dispatch relooper,
    // which handles any reducible CFG correctly.
    if then_reaches_header && else_reaches_header {
        return Err(WasmCodegenError::unsupported(
            "while body inner-if: both arms continue to header (needs relooper)",
        ));
    }

    // If else arm is the short arm, invert the condition.
    let invert = !then_has_return && !then_reaches_else && !then_reaches_header && else_has_return;

    if !then_has_return && !then_reaches_else && !then_reaches_header && !else_has_return {
        return Err(WasmCodegenError::unsupported(
            "while body inner-if: cannot determine short vs through arm",
        ));
    }

    let (if_arm, through_arm) = if invert { (else_block, then_block) } else { (then_block, else_block) };

    self.emit_operand(cond)?;
    self.wfunc.instruction(&W::I32WrapI64);
    if invert { self.wfunc.instruction(&W::I32Eqz); }
    self.wfunc.instruction(&W::If(BlockType::Empty));

    // Emit the if_arm chain: Return / Goto(header) / Goto(through_arm) → fall through.
    let mut current = if_arm;
    loop {
        let curr_idx = self.block_index(current)?;
        if self.visited[curr_idx] {
            break; // reached through_arm already visited — fall through
        }
        self.visited[curr_idx] = true;
        let instrs = self.func.blocks[curr_idx].instructions.clone();
        for inst in &instrs { self.emit_instruction(inst)?; }
        let term = self.func.blocks[curr_idx].terminator.clone();
        match term {
            Terminator::Return(val) => {
                if let Some(op) = &val { self.emit_operand(op)?; }
                self.wfunc.instruction(&W::Return);
                break;
            }
            Terminator::Goto(b) if b == loop_header => {
                self.wfunc.instruction(&W::Br(1)); // inside if: br 1 = loop
                break;
            }
            Terminator::Goto(b) if b == through_arm => {
                break; // fall through to through_arm after end-if
            }
            Terminator::Goto(next) => { current = next; }
            _ => return Err(WasmCodegenError::unsupported(
                "while body inner-if arm: unsupported terminator",
            )),
        }
    }

    self.wfunc.instruction(&W::End); // end inner if

    // Emit the through_arm chain until Goto(loop_header) or Return.
    let mut current = through_arm;
    loop {
        let curr_idx = self.block_index(current)?;
        if self.visited[curr_idx] {
            self.wfunc.instruction(&W::Br(0));
            return Ok(());
        }
        self.visited[curr_idx] = true;
        let instrs = self.func.blocks[curr_idx].instructions.clone();
        for inst in &instrs { self.emit_instruction(inst)?; }
        let term = self.func.blocks[curr_idx].terminator.clone();
        match term {
            Terminator::Goto(b) if b == loop_header => {
                self.wfunc.instruction(&W::Br(0));
                return Ok(());
            }
            Terminator::Goto(next) => { current = next; }
            Terminator::Return(val) => {
                if let Some(op) = &val { self.emit_operand(op)?; }
                self.wfunc.instruction(&W::Return);
                return Ok(());
            }
            _ => return Err(WasmCodegenError::unsupported(
                "while body through-arm: unsupported terminator",
            )),
        }
    }
}

/// Emit an if/else: detect the join point (the first block both arms
/// reach), emit then/else inside a wasm `if`, then continue with join.
fn emit_if_else(
    &mut self,
    cond: &Operand,
    then_block: BlockId,
    else_block: BlockId,
) -> Result<(), WasmCodegenError> {
    let join = find_common_join(self.func, &self.id_to_index, then_block, else_block);
    // Short-circuit `&&`: the else branch IS the join (e.g. bb_join = return block).
    // Don't put it inside the wasm `else`; let the then arm fall through to it after `end`.
    let else_is_join = join.map(|j| j == else_block).unwrap_or(false);

    self.emit_operand(cond)?;
    self.wfunc.instruction(&W::I32WrapI64);
    self.wfunc.instruction(&W::If(BlockType::Empty));

    // then arm
    self.emit_arm(then_block, join)?;

    if !else_is_join {
        self.wfunc.instruction(&W::Else);
        self.emit_arm(else_block, join)?;
    }

    self.wfunc.instruction(&W::End);

    // Continue with the join block (if any).
    if let Some(j) = join {
        let j_idx = self.block_index(j)?;
        if !self.visited[j_idx] {
            self.emit_block(j)?;
        }
    }
    Ok(())
}

/// Emit one arm of an if/else: the block's instructions, but stop before
/// emitting a Goto to the join point (the `if` block in WASM handles the
/// continuation).
fn emit_arm(&mut self, arm: BlockId, join: Option<BlockId>) -> Result<(), WasmCodegenError> {
    let idx = self.block_index(arm)?;
    if self.visited[idx] {
        return Err(WasmCodegenError::unsupported(
            "if-arm shares a block with another path",
        ));
    }
    self.visited[idx] = true;
    let block = &self.func.blocks[idx];
    for inst in &block.instructions {
        self.emit_instruction(inst)?;
    }
    // Snapshot terminator so we can release the borrow on `self`.
    let terminator = block.terminator.clone();
    match terminator {
        Terminator::Goto(t) if Some(t) == join => {
            // Fall through — the outer `if` continues at the join.
        }
        Terminator::Return(ref v) => {
            if let Some(op) = v.as_ref() {
                self.emit_operand(op)?;
            }
            self.wfunc.instruction(&W::Return);
        }
        Terminator::Goto(t) => {
            // Tail-call into another block within this arm.
            self.emit_block(t)?;
        }
        Terminator::Branch {
            ref cond,
            then_block,
            else_block,
        } => {
            // Nested if/else inside an arm (chained `elif`). Emit it
            // recursively, sharing the *outer* join point so all arms
            // converge to the same wasm continuation.
            self.emit_if_else_with_join(cond, then_block, else_block, join)?;
        }
        Terminator::Switch { .. } => {
            // A `match` nested inside an if arm that this structured path
            // can't express: fail so the dispatch relooper handles the
            // function. A silent W::Unreachable here becomes a runtime
            // trap inside code that compiled without any diagnostic.
            return Err(WasmCodegenError::unsupported(
                "match inside if arm; relooper fallback",
            ));

        }
        Terminator::Unreachable => {
            self.wfunc.instruction(&W::Unreachable);
        }
    }
    Ok(())
}

/// Like `emit_if_else` but uses a caller-supplied join (used when emitting
/// nested arms inside an outer if/else).
fn emit_if_else_with_join(
    &mut self,
    cond: &Operand,
    then_block: BlockId,
    else_block: BlockId,
    join: Option<BlockId>,
) -> Result<(), WasmCodegenError> {
    let else_is_join = join.map(|j| j == else_block).unwrap_or(false);
    self.emit_operand(cond)?;
    self.wfunc.instruction(&W::I32WrapI64);
    self.wfunc.instruction(&W::If(BlockType::Empty));
    self.emit_arm(then_block, join)?;
    if !else_is_join {
        self.wfunc.instruction(&W::Else);
        self.emit_arm(else_block, join)?;
    }
    self.wfunc.instruction(&W::End);
    Ok(())
}

// -----------------------------------------------------------------------
// Instruction-level lowering
// -----------------------------------------------------------------------

/// Whether emitting `rv` leaves exactly one value on the wasm stack. Used
/// to decide if a discarded (void-dest) statement result must be dropped.
/// Only `Call` to a void builtin or a void user function leaves nothing;
/// every other rvalue pushes one value.
fn rvalue_leaves_value(&self, rv: &RValue) -> bool {
    match rv {
        RValue::Call { func, .. } => {
            const VOID_BUILTINS: &[&str] = &[
                "println", "print", "eprintln", "eprint", "array_set", "alert",
                "canvas_clear", "canvas_fill_rect", "dom_set_text", "sleep", "sleep_ms",
            ];
            !VOID_BUILTINS.contains(&func.as_str())
                && !self.cg.void_user_fns.contains(func.as_str())
        }
        // Statement-level Nop-like rvalues don't occur here; every other
        // rvalue (BinOp, Array, Map, Closure, CallIndirect to non-void, ...)
        // leaves a value.
        _ => true,
    }
}

fn emit_instruction(&mut self, inst: &Instruction) -> Result<(), WasmCodegenError> {
    match inst {
        Instruction::Assign { dest, value } => {
            // If the assigned local is `void`-typed, treat this as a
            // statement: emit the rvalue for its side effect and skip
            // the LocalSet (the call leaves nothing on the stack).
            let dest_is_void = self
                .func
                .locals
                .get(dest.0 as usize)
                .map(|l| is_void(&l.ty))
                .unwrap_or(false);
            if dest_is_void {
                // Discarded statement (e.g. `push(r, i)` with the result
                // thrown away). Emit for side effect, but if the rvalue
                // still LEAVES a value on the stack (push, str_concat, a
                // non-void call, ...), drop it -- else the wasm stack is
                // imbalanced (the bug behind `filter` and any discarded
                // value-returning call inside a while+if).
                self.emit_rvalue(value)?;
                if self.rvalue_leaves_value(value) {
                    self.wfunc.instruction(&W::Drop);
                }
            } else {
                self.emit_rvalue(value)?;
                self.wfunc.instruction(&W::LocalSet(dest.0));
            }
        }
        Instruction::Nop | Instruction::DebugLine(_) => {}
        Instruction::ArcRetain { .. }
        | Instruction::ArcRelease { .. }
        | Instruction::Drop { .. } => {
            // In v0.1 we have no heap, so ARC ops are no-ops.
        }
        Instruction::StoreField { object, field, value } => {
            let struct_name = match self.operand_ty(object) {
                Some(MirType::Struct(n)) => n,
                // Array element stores: MIR lowers `arr[i].field = v` as
                // StoreField { object: Ptr(Struct(name)), ... } so the LLVM
                // backend can emit an inttoptr GEP. In WASM, Ptr is an i64
                // handle; extract the struct name and treat the same way.
                Some(MirType::Ptr(inner)) => match inner.as_ref() {
                    MirType::Struct(n) => n.clone(),
                    _ => return Err(WasmCodegenError::unsupported(
                        "StoreField on non-struct pointer",
                    )),
                },
                _ => return Err(WasmCodegenError::unsupported(
                    "StoreField on non-struct operand",
                )),
            };
            let field_name = field.clone();
            let (field_idx, field_ty) = self.cg.struct_defs
                .get(&struct_name)
                .and_then(|fs| {
                    fs.iter().enumerate()
                        .find(|(_, (n, _))| n == &field_name)
                        .map(|(i, (_, t))| (i as i32, t.clone()))
                })
                .unwrap_or((0, MirType::I64));
            let array_set_idx = self.cg.array_set_idx;
            self.emit_operand(object)?;
            self.wfunc.instruction(&W::I32Const(field_idx));
            self.emit_operand(value)?;
            // f64 fields must be stored as i64 bit-patterns.
            if matches!(field_ty, MirType::F64) {
                self.wfunc.instruction(&W::I64ReinterpretF64);
            }
            self.wfunc.instruction(&W::Call(array_set_idx));
        }
        Instruction::StoreDeref { .. }
        | Instruction::Spawn { .. }
        | Instruction::Send { .. }
        | Instruction::Receive { .. }
        | Instruction::ActorSpawn { .. }
        | Instruction::ActorSend { .. }
        | Instruction::ActorStateLoad { .. }
        | Instruction::ActorStateStore { .. } => {
            return Err(WasmCodegenError::unsupported(
                "heap operations / spawn / channels / actors (v0.1 is compute-only)",
            ));
        }
    }
    Ok(())
}

fn emit_rvalue(&mut self, rv: &RValue) -> Result<(), WasmCodegenError> {
    match rv {
        RValue::Use(op) => self.emit_operand(op)?,
        RValue::ConstInt(v) => {
            self.wfunc.instruction(&W::I64Const(*v));
        }
        RValue::ConstFloat(v) => {
            self.wfunc.instruction(&W::F64Const(*v));
        }
        RValue::ConstBool(b) => {
            self.wfunc.instruction(&W::I64Const(if *b { 1 } else { 0 }));
        }
        RValue::ConstString(s) => {
            // v0.2: push a single packed i64 value with low32 = offset,
            // high32 = length. This makes strings first-class — they
            // survive in locals, parameters, and returns without a side
            // table, and `len(s)` is just a shift.
            let (offset, len) = self.cg.intern_string(s);
            let packed = ((len as u64) << 32) | (offset as u64);
            self.wfunc.instruction(&W::I64Const(packed as i64));
        }
        RValue::ConstNone => {
            self.wfunc.instruction(&W::I64Const(0));
        }
        RValue::BinOp { op, left, right } => {
            let lty = self.operand_ty(left).unwrap_or(MirType::I64);
            let rty = self.operand_ty(right).unwrap_or(MirType::I64);
            if matches!(op, MirBinOp::Add)
                && matches!(lty, MirType::Str)
                && matches!(rty, MirType::Str)
            {
                self.emit_operand(left)?;
                self.emit_unpack_string();
                self.emit_operand(right)?;
                self.emit_unpack_string();
                self.wfunc.instruction(&W::Call(self.cg.string_concat_idx));
            } else if matches!(lty, MirType::F64 | MirType::F32)
                || matches!(rty, MirType::F64 | MirType::F32)
            {
                self.emit_operand(left)?;
                self.emit_operand(right)?;
                self.emit_binop_f64(*op)?;
            } else {
                self.emit_operand(left)?;
                self.emit_operand(right)?;
                self.emit_binop(*op)?;
            }
        }
        RValue::StringConcat(parts) => {
            self.emit_string_concat(parts)?;
        }
        RValue::UnOp { op, operand } => {
            match op {
                MirUnOp::Neg => {
                    let ty = self.operand_ty(operand).unwrap_or(MirType::I64);
                    if matches!(ty, MirType::F64 | MirType::F32) {
                        self.emit_operand(operand)?;
                        if matches!(ty, MirType::F32) {
                            self.wfunc.instruction(&W::F64PromoteF32);
                        }
                        self.wfunc.instruction(&W::F64Neg);
                    } else {
                        // Integer negate: 0 - x; use scratch local to preserve stack order.
                        self.emit_operand(operand)?;
                        let scratch = self.cg_scratch_local();
                        self.wfunc.instruction(&W::LocalSet(scratch));
                        self.wfunc.instruction(&W::I64Const(0));
                        self.wfunc.instruction(&W::LocalGet(scratch));
                        self.wfunc.instruction(&W::I64Sub);
                    }
                }
                _ => {
                    self.emit_operand(operand)?;
                    self.emit_unop(*op)?;
                }
            }
        }
        RValue::Call { func, args } => {
            self.emit_call(func, args)?;
        }
        RValue::Cast { operand, ty } => {
            let src_ty = self.operand_ty(operand).unwrap_or(MirType::I64);
            self.emit_operand(operand)?;
            // f64/f32 source requires explicit truncation to integer.
            if matches!(src_ty, MirType::F64 | MirType::F32) {
                if matches!(src_ty, MirType::F32) {
                    self.wfunc.instruction(&W::F64PromoteF32);
                }
                // Use SATURATING (non-trapping) truncation: the trapping
                // I64TruncF64S crashed the module with "float
                // unrepresentable" on any out-of-range value (e.g.
                // 1e19 as i64), whereas native saturates. Unsigned
                // destinations use the U variant to reach the upper half
                // of the range (backlog #61/#92). Narrow ints saturate to
                // i64 then clamp to range — the old path emitted an
                // I64And mask on an f64 stack value (type-invalid, #3).
                match ty {
                    MirType::I64 => {
                        self.wfunc.instruction(&W::I64TruncSatF64S);
                    }
                    MirType::U64 => {
                        self.wfunc.instruction(&W::I64TruncSatF64U);
                    }
                    MirType::I32 => {
                        self.wfunc.instruction(&W::I32TruncSatF64S);
                        self.wfunc.instruction(&W::I64ExtendI32S);
                    }
                    MirType::U32 => {
                        self.wfunc.instruction(&W::I32TruncSatF64U);
                        self.wfunc.instruction(&W::I64ExtendI32U);
                    }
                    MirType::I8 | MirType::I16 | MirType::U8 | MirType::U16 => {
                        self.wfunc.instruction(&W::I64TruncSatF64S);
                        let (lo, hi) = narrow_int_range(ty);
                        self.emit_i64_clamp(lo, hi);
                    }
                    MirType::F64 => { /* f32->f64 already promoted, f64->f64 no-op */ }
                    _ => { self.emit_cast(ty)?; }
                }
            } else {
                self.emit_cast(ty)?;
            }
        }
        // -------------------------------------------------------------
        // WASM v0.3: Array literal — `[a, b, c]`
        // Lowers to:  arr = array_new(n); array_set(arr, 0, a); ...; arr
        // -------------------------------------------------------------
        RValue::Array(elems) => {
            // Push count, call array_new -> i64 packed array handle.
            self.wfunc.instruction(&W::I32Const(elems.len() as i32));
            self.wfunc.instruction(&W::Call(self.cg.array_new_idx));
            // Stash the array handle in scratch so we can re-use it.
            let scratch = self.cg_scratch_local();
            self.wfunc.instruction(&W::LocalSet(scratch));
            // For each element: load array, push idx, push value, set.
            for (i, elem) in elems.iter().enumerate() {
                self.wfunc.instruction(&W::LocalGet(scratch));
                self.wfunc.instruction(&W::I32Const(i as i32));
                self.emit_operand(elem)?;
                self.wfunc.instruction(&W::Call(self.cg.array_set_idx));
            }
            // Leave the array handle on the stack as the rvalue result.
            self.wfunc.instruction(&W::LocalGet(scratch));
        }
        // -------------------------------------------------------------
        // WASM v0.3: Array indexing — `arr[i]`
        // -------------------------------------------------------------
        RValue::Index { object, index } => {
            self.emit_operand(object)?;            // packed i64 array
            self.emit_operand(index)?;             // index i64
            self.wfunc.instruction(&W::I32WrapI64);// -> i32 index
            self.wfunc.instruction(&W::Call(self.cg.array_get_idx));
        }
        // -----------------------------------------------------------------
        // WASM v0.4: Struct literal — `Foo { a: x, b: y }`
        // Represent structs as i64 array handles: alloc N slots, fill each.
        // -----------------------------------------------------------------
        RValue::Struct { name, fields } => {
            let n = fields.len() as i32;

            self.wfunc.instruction(&W::I32Const(n));
            self.wfunc.instruction(&W::Call(self.cg.array_new_idx));
            let scratch = self.cg_scratch_local();
            self.wfunc.instruction(&W::LocalSet(scratch));
            // Resolve field order and types from struct_defs for stable slot indices.
            let struct_name = name.clone();
            let field_defs: Vec<(String, MirType)> = self.cg.struct_defs
                .get(&struct_name)
                .cloned()
                .unwrap_or_else(|| fields.iter().map(|(n, _)| (n.clone(), MirType::I64)).collect());
            let array_set_idx = self.cg.array_set_idx;
            for (fname, fval) in fields {
                let (idx, field_ty) = field_defs.iter().enumerate()
                    .find(|(_, (n, _))| n == fname)
                    .map(|(i, (_, t))| (i as i32, t.clone()))
                    .unwrap_or((0, MirType::I64));
                self.wfunc.instruction(&W::LocalGet(scratch));
                self.wfunc.instruction(&W::I32Const(idx));
                self.emit_operand(fval)?;
                // f64 fields must be stored as i64 bit-patterns.
                if matches!(field_ty, MirType::F64) {
                    self.wfunc.instruction(&W::I64ReinterpretF64);
                }
                self.wfunc.instruction(&W::Call(array_set_idx));
            }
            self.wfunc.instruction(&W::LocalGet(scratch));
        }
        // -----------------------------------------------------------------
        // WASM v0.4: Struct field read — `obj.field`
        // -----------------------------------------------------------------
        RValue::Field { object, field } => {
            match self.operand_ty(object) {
                Some(MirType::Tuple(elem_types)) => {
                    // Tuple field access: field name is "0", "1", ... (numeric index as string).
                    let idx = field.parse::<i32>().unwrap_or(0);
                    let field_ty = elem_types.get(idx as usize).cloned().unwrap_or(MirType::I64);
                    let array_get_idx = self.cg.array_get_idx;
                    self.emit_operand(object)?;
                    self.wfunc.instruction(&W::I32Const(idx));
                    self.wfunc.instruction(&W::Call(array_get_idx));
                    if matches!(field_ty, MirType::F64) {
                        self.wfunc.instruction(&W::F64ReinterpretI64);
                    }
                }
                Some(MirType::Struct(struct_name)) => {
                    let field_name = field.clone();
                    let (field_idx, field_ty) = self.cg.struct_defs
                        .get(&struct_name)
                        .and_then(|fs| {
                            fs.iter().enumerate()
                                .find(|(_, (n, _))| n == &field_name)
                                .map(|(i, (_, t))| (i as i32, t.clone()))
                        })
                        .unwrap_or((0, MirType::I64));
                    let array_get_idx = self.cg.array_get_idx;
                    self.emit_operand(object)?;
                    self.wfunc.instruction(&W::I32Const(field_idx));
                    self.wfunc.instruction(&W::Call(array_get_idx));
                    // f64 fields are stored as their i64 bit-pattern; reinterpret on read.
                    if matches!(field_ty, MirType::F64) {
                        self.wfunc.instruction(&W::F64ReinterpretI64);
                    }
                }
                _ => return Err(WasmCodegenError::unsupported(&format!(
                    "field access `{field}` on non-struct/tuple operand"
                ))),
            }
        }
        // -----------------------------------------------------------------
        // WASM v2.4: Enum variant construction
        // Encoding: [tag:i64, field0:i64, field1:i64, ...]
        //   slot 0 = variant_idx (the tag)
        //   slots 1..n = payload fields
        // -----------------------------------------------------------------
        RValue::EnumVariant { enum_name: _, variant_idx, fields } => {
            let n_slots = 1 + fields.len();
            self.wfunc.instruction(&W::I32Const(n_slots as i32));
            self.wfunc.instruction(&W::Call(self.cg.array_new_idx));
            let scratch = self.cg_scratch_local();
            self.wfunc.instruction(&W::LocalSet(scratch));
            // Store tag at slot 0.
            self.wfunc.instruction(&W::LocalGet(scratch));
            self.wfunc.instruction(&W::I32Const(0));
            self.wfunc.instruction(&W::I64Const(*variant_idx as i64));
            let array_set_idx = self.cg.array_set_idx;
            self.wfunc.instruction(&W::Call(array_set_idx));
            // Store each payload field at slots 1, 2, ...
            for (i, field_op) in fields.iter().enumerate() {
                self.wfunc.instruction(&W::LocalGet(scratch));
                self.wfunc.instruction(&W::I32Const((i + 1) as i32));
                self.emit_operand(field_op)?;
                self.wfunc.instruction(&W::Call(array_set_idx));
            }
            self.wfunc.instruction(&W::LocalGet(scratch));
        }
        // -----------------------------------------------------------------
        // WASM v2.4: Enum tag extraction (for Switch dispatch)
        // -----------------------------------------------------------------
        RValue::EnumTag { operand } => {
            self.emit_operand(operand)?;
            self.wfunc.instruction(&W::I32Const(0));
            self.wfunc.instruction(&W::Call(self.cg.array_get_idx));
        }
        // -----------------------------------------------------------------
        // WASM v2.4: Enum payload field extraction
        // -----------------------------------------------------------------
        RValue::EnumPayload { operand, enum_name: _, variant_idx: _, field_idx } => {
            self.emit_operand(operand)?;
            self.wfunc.instruction(&W::I32Const((*field_idx + 1) as i32));
            self.wfunc.instruction(&W::Call(self.cg.array_get_idx));
        }
        // -----------------------------------------------------------------
        // WASM v2.5: Tuple construction — `(a, b, c)`
        // Identical to array/struct: allocate N slots, fill each, leave handle.
        // -----------------------------------------------------------------
        RValue::Tuple(elems) => {
            self.wfunc.instruction(&W::I32Const(elems.len() as i32));
            self.wfunc.instruction(&W::Call(self.cg.array_new_idx));
            let scratch = self.cg_scratch_local();
            self.wfunc.instruction(&W::LocalSet(scratch));
            let array_set_idx = self.cg.array_set_idx;
            for (i, elem) in elems.iter().enumerate() {
                self.wfunc.instruction(&W::LocalGet(scratch));
                self.wfunc.instruction(&W::I32Const(i as i32));
                self.emit_operand(elem)?;
                self.wfunc.instruction(&W::Call(array_set_idx));
            }
            self.wfunc.instruction(&W::LocalGet(scratch));
        }
        // Map literal `{}` / `{k: v, ...}`: host-backed handle. map_new(),
        // then map_insert_str(handle, key, value) per entry.
        RValue::Map(entries) => {
            self.wfunc.instruction(&W::Call(self.cg.map_new_idx));
            let scratch = self.cg_scratch_local();
            self.wfunc.instruction(&W::LocalSet(scratch));
            for (k, v) in entries {
                self.wfunc.instruction(&W::LocalGet(scratch)); // handle
                self.emit_operand(k)?; // packed key string
                self.emit_operand(v)?; // i64 value
                self.wfunc.instruction(&W::Call(self.cg.map_insert_str_idx));
                self.wfunc.instruction(&W::Drop); // handle passthrough, discard
            }
            self.wfunc.instruction(&W::LocalGet(scratch));
        }
        // Closure value: a heap env array `[thunk_idx, cap0, cap1, ...]`
        // for EVERY closure (no-capture -> just `[thunk_idx]`). The uniform
        // env representation gives call_indirect one signature per closure
        // shape (env, user_args) -> ret via the thunk.
        RValue::Closure { func_name, captures } => {
            let lambda_idx = *self.cg.fn_indices.get(func_name.as_str()).ok_or_else(|| {
                WasmCodegenError::unsupported(&format!(
                    "closure over unknown function `{func_name}`"
                ))
            })?;
            let thunk_idx = self
                .cg
                .closure_thunk_idx
                .get(func_name.as_str())
                .copied()
                .unwrap_or(lambda_idx);
            let n = (captures.len() + 1) as i32;
            self.wfunc.instruction(&W::I32Const(n));
            self.wfunc.instruction(&W::Call(self.cg.array_new_idx));
            let scratch = self.cg_scratch_local();
            self.wfunc.instruction(&W::LocalSet(scratch));
            // slot 0 = thunk table index.
            self.wfunc.instruction(&W::LocalGet(scratch));
            self.wfunc.instruction(&W::I32Const(0));
            self.wfunc.instruction(&W::I64Const(thunk_idx as i64));
            self.wfunc.instruction(&W::Call(self.cg.array_set_idx));
            // slots 1.. = captures.
            for (i, cap) in captures.iter().enumerate() {
                self.wfunc.instruction(&W::LocalGet(scratch));
                self.wfunc.instruction(&W::I32Const((i + 1) as i32));
                self.emit_operand(cap)?;
                self.wfunc.instruction(&W::Call(self.cg.array_set_idx));
            }
            self.wfunc.instruction(&W::LocalGet(scratch));
        }
        // Indirect call through a closure value (its env array). Dispatch
        // via the thunk stored in env[0]: thunk(env, user_args...) unpacks
        // the captures and calls the real lambda.
        RValue::CallIndirect { callee, args } => {
            let callee_ty = self.operand_ty(callee).unwrap_or(MirType::I64);
            let ret_ty = match &callee_ty {
                MirType::Function { ret, .. } => (**ret).clone(),
                _ => MirType::I64,
            };
            // Thunk signature: (i64 env, user_arg_types...) -> ret.
            let mut wparams: Vec<ValType> = vec![ValType::I64]; // env
            for a in args {
                wparams.push(lower_type(&self.operand_ty(a).unwrap_or(MirType::I64)).unwrap_or(ValType::I64));
            }
            let wret = if is_void(&ret_ty) {
                None
            } else {
                Some(lower_type(&ret_ty).unwrap_or(ValType::I64))
            };
            let type_index = self.cg.indirect_type_index(&wparams, wret);
            // Stash the env in scratch 2 (arg emission below uses scratch 1
            // for string unpacking, so env survives), then push
            // (env, user_args...) then the thunk index (env[0]).
            let env = self.cg_scratch_local2();
            self.emit_operand(callee)?;
            self.wfunc.instruction(&W::LocalSet(env));
            self.wfunc.instruction(&W::LocalGet(env)); // arg0 = env
            for a in args {
                self.emit_operand(a)?;
            }
            // table index = env[0].
            self.wfunc.instruction(&W::LocalGet(env));
            self.wfunc.instruction(&W::I32Const(0));
            self.wfunc.instruction(&W::Call(self.cg.array_get_idx));
            self.wfunc.instruction(&W::I32WrapI64);
            self.wfunc.instruction(&W::CallIndirect {
                type_index,
                table_index: 0,
            });
        }
        other => {
            return Err(WasmCodegenError::unsupported(&format!(
                "rvalue `{}` (v0.5 supports scalars, calls, casts, arrays, indexing, maps, \
                 no-capture closures)",
                debug_short(other)
            )));
        }
    }
    Ok(())
}

fn emit_operand(&mut self, op: &Operand) -> Result<(), WasmCodegenError> {
    match op {
        Operand::Local(id) => {
            self.wfunc.instruction(&W::LocalGet(id.0));
        }
        Operand::Constant(c) => match c {
            Constant::Int(v) => {
                self.wfunc.instruction(&W::I64Const(*v));
            }
            Constant::Float(v) => {
                self.wfunc.instruction(&W::F64Const(*v));
            }
            Constant::Bool(b) => {
                self.wfunc.instruction(&W::I64Const(if *b { 1 } else { 0 }));
            }
            Constant::Str(s) => {
                let (offset, len) = self.cg.intern_string(s);
                let packed = ((len as u64) << 32) | (offset as u64);
                self.wfunc.instruction(&W::I64Const(packed as i64));
            }
            Constant::None => {
                self.wfunc.instruction(&W::I64Const(0));
            }
        },
    }
    Ok(())
}

fn emit_binop(&mut self, op: MirBinOp) -> Result<(), WasmCodegenError> {
    // For v0.1 we operate on i64 by default. Float ops would need a type
    // tag we don't have yet at the rvalue level — the MIR doesn't currently
    // distinguish "f64 add" from "i64 add" in the op variant, it relies on
    // the lowering knowing the operand types. We'll improve this later.
    let inst = match op {
        MirBinOp::Add => W::I64Add,
        MirBinOp::Sub => W::I64Sub,
        MirBinOp::Mul => W::I64Mul,
        MirBinOp::Div => W::I64DivS,
        MirBinOp::Mod => W::I64RemS,
        MirBinOp::Pow => {
            return Err(WasmCodegenError::unsupported(
                "integer exponent (use a loop or import a helper for v0.1)",
            ));
        }
        MirBinOp::Eq => W::I64Eq,
        MirBinOp::Neq => W::I64Ne,
        MirBinOp::Lt => W::I64LtS,
        MirBinOp::Gt => W::I64GtS,
        MirBinOp::LtEq => W::I64LeS,
        MirBinOp::GtEq => W::I64GeS,
        MirBinOp::And => W::I64And,
        MirBinOp::Or => W::I64Or,
        MirBinOp::BitAnd => W::I64And,
        MirBinOp::BitOr => W::I64Or,
        MirBinOp::BitXor => W::I64Xor,
        MirBinOp::Shl => W::I64Shl,
        MirBinOp::Shr => W::I64ShrS,
    };
    self.wfunc.instruction(&inst);
    // WASM comparison ops return i32, but our value model is i64. Extend.
    if matches!(
        op,
        MirBinOp::Eq
            | MirBinOp::Neq
            | MirBinOp::Lt
            | MirBinOp::Gt
            | MirBinOp::LtEq
            | MirBinOp::GtEq
    ) {
        self.wfunc.instruction(&W::I64ExtendI32U);

    }
    Ok(())
}

fn emit_unop(&mut self, op: MirUnOp) -> Result<(), WasmCodegenError> {
    match op {
        MirUnOp::Neg => {
            // Handled in emit_rvalue UnOp arm (needs type info + scratch local).
            // This path should not be reached.
            unreachable!("MirUnOp::Neg must be handled in emit_rvalue");
        }
        MirUnOp::Not => {
            // logical not: x == 0
            self.wfunc.instruction(&W::I64Eqz);
            self.wfunc.instruction(&W::I64ExtendI32U);
        }
        MirUnOp::BitNot => {
            self.wfunc.instruction(&W::I64Const(-1));
            self.wfunc.instruction(&W::I64Xor);
        }
    }
    Ok(())
}

/// Get the MIR type of an operand for codegen dispatch (println/len/etc).
fn operand_ty(&self, op: &Operand) -> Option<MirType> {
    match op {
        Operand::Local(id) => self
            .func
            .locals
            .iter()
            .find(|l| l.id.0 == id.0)
            .map(|l| l.ty.clone()),
        Operand::Constant(c) => Some(match c {
            Constant::Int(_) => MirType::I64,
            Constant::Float(_) => MirType::F64,
            Constant::Bool(_) => MirType::Bool,
            Constant::Str(_) => MirType::Str,
            Constant::None => MirType::Void,
        }),
    }
}

/// Emit code that unpacks a packed-string i64 (on the stack) into two
/// i32 values (offset, len) on the stack. Consumes the i64.
fn emit_unpack_string(&mut self) {
    // Stack: [packed:i64]
    // We want: [offset:i32, len:i32]
    // Use a temp local in the wfunc to dup the value. But we don't have
    // a way to allocate fresh locals here — instead, use the wasm
    // pattern: dup via local.tee/local.get if a scratch i64 local exists,
    // OR use bit math without dup by computing both halves with one
    // load via i32 wrap and shr+wrap. Simplest: TEE into scratch.
    //
    // We use the LAST declared local as a scratch i64. To make that
    // available unconditionally we always reserve one extra i64 local
    // at the end of every function (see emit_function).
    let scratch = self.cg_scratch_local();
    // [packed]
    self.wfunc.instruction(&W::LocalTee(scratch));
    // [packed]
    self.wfunc.instruction(&W::I32WrapI64);
    // [offset:i32]
    self.wfunc.instruction(&W::LocalGet(scratch));
    self.wfunc.instruction(&W::I64Const(32));
    self.wfunc.instruction(&W::I64ShrU);
    self.wfunc.instruction(&W::I32WrapI64);
    // [offset:i32, len:i32]
}

/// Return the WASM local index of the scratch i64 local appended at
/// the very end of every function (see emit_function).
fn cg_scratch_local(&self) -> u32 {
    // First reserved i64 local after all user locals.
    self.func.locals.len() as u32
}

/// Clamp the i64 value on top of the stack to `[lo, hi]` (used for
/// narrow-int saturating casts). `select` returns its first operand when
/// the condition is non-zero.
fn emit_i64_clamp(&mut self, lo: i64, hi: i64) {
    let s = self.cg_scratch_local();
    self.wfunc.instruction(&W::LocalSet(s));
    // s = (s < lo) ? lo : s
    self.wfunc.instruction(&W::I64Const(lo));
    self.wfunc.instruction(&W::LocalGet(s));
    self.wfunc.instruction(&W::LocalGet(s));
    self.wfunc.instruction(&W::I64Const(lo));
    self.wfunc.instruction(&W::I64LtS);
    self.wfunc.instruction(&W::Select);
    self.wfunc.instruction(&W::LocalSet(s));
    // s = (s > hi) ? hi : s
    self.wfunc.instruction(&W::I64Const(hi));
    self.wfunc.instruction(&W::LocalGet(s));
    self.wfunc.instruction(&W::LocalGet(s));
    self.wfunc.instruction(&W::I64Const(hi));
    self.wfunc.instruction(&W::I64GtS);
    self.wfunc.instruction(&W::Select);
}

/// Second reserved i64 scratch (holds a closure env across arg emission).
fn cg_scratch_local2(&self) -> u32 {
    self.func.locals.len() as u32 + 1
}

/// Third reserved i64 scratch: the dispatch relooper's program counter.
fn cg_pc_local(&self) -> u32 {
    self.func.locals.len() as u32 + 2
}

/// Emit the whole function body as a dispatch loop over a program counter.
/// The pc is a dense block index (position in `func.blocks`); block 0 is the
/// entry. Layout:
///   pc = 0
///   loop
///     if pc==0 { <block 0>; set pc; br 1 (or return) }
///     else if pc==1 { <block 1>; set pc; br 2 } ...
///     else { unreachable }
///   end
/// Inside block i's `if` the loop is `i+1` frames up, so a continue is
/// `br (i+1)`.
fn emit_relooper(&mut self) -> Result<(), WasmCodegenError> {
    let n = self.func.blocks.len();
    let pc = self.cg_pc_local();
    // Entry = block 0.
    self.wfunc.instruction(&W::I64Const(0));
    self.wfunc.instruction(&W::LocalSet(pc));
    self.wfunc.instruction(&W::Loop(BlockType::Empty));
    for i in 0..n {
        self.wfunc.instruction(&W::LocalGet(pc));
        self.wfunc.instruction(&W::I64Const(i as i64));
        self.wfunc.instruction(&W::I64Eq);
        self.wfunc.instruction(&W::If(BlockType::Empty));
        let instrs = self.func.blocks[i].instructions.clone();
        for inst in &instrs {
            self.emit_instruction(inst)?;
        }
        let term = self.func.blocks[i].terminator.clone();
        self.emit_relooper_terminator(&term, i, pc)?;
        self.wfunc.instruction(&W::Else);
    }
    // pc out of range: unreachable.
    self.wfunc.instruction(&W::Unreachable);
    for _ in 0..n {
        self.wfunc.instruction(&W::End); // close each `if`
    }
    self.wfunc.instruction(&W::End); // close `loop`
    // The loop never falls through (every block ends in br/return), so
    // anything here is unreachable; keep the stack polymorphic.
    self.wfunc.instruction(&W::Unreachable);
    Ok(())
}

/// Emit a block terminator inside the relooper: set the pc to the successor
/// and continue the loop (`br (block_i + 1)`), or return/unreachable.
fn emit_relooper_terminator(
    &mut self,
    term: &Terminator,
    block_i: usize,
    pc: u32,
) -> Result<(), WasmCodegenError> {
    let cont = (block_i + 1) as u32; // br depth to the enclosing loop
    match term {
        Terminator::Goto(t) => {
            let idx = self.block_index(*t)?;
            self.wfunc.instruction(&W::I64Const(idx as i64));
            self.wfunc.instruction(&W::LocalSet(pc));
            self.wfunc.instruction(&W::Br(cont));
        }
        Terminator::Branch { cond, then_block, else_block } => {
            let ti = self.block_index(*then_block)? as i64;
            let ei = self.block_index(*else_block)? as i64;
            // pc = cond ? ti : ei   (via `select`, no extra control frame)
            self.wfunc.instruction(&W::I64Const(ti));
            self.wfunc.instruction(&W::I64Const(ei));
            self.emit_operand(cond)?;
            self.wfunc.instruction(&W::I32WrapI64);
            self.wfunc.instruction(&W::Select);
            self.wfunc.instruction(&W::LocalSet(pc));
            self.wfunc.instruction(&W::Br(cont));
        }
        Terminator::Return(val) => {
            if let Some(op) = val {
                self.emit_operand(op)?;
            }
            self.wfunc.instruction(&W::Return);
        }
        Terminator::Switch { value, targets, default } => {
            let di = self.block_index(*default)? as i64;
            self.wfunc.instruction(&W::I64Const(di));
            self.wfunc.instruction(&W::LocalSet(pc));
            // pc = (value == case) ? case_target : pc, folded over cases.
            for (case, tgt) in targets {
                let ti = self.block_index(*tgt)? as i64;
                self.wfunc.instruction(&W::I64Const(ti));
                self.wfunc.instruction(&W::LocalGet(pc));
                self.emit_operand(value)?;
                self.wfunc.instruction(&W::I64Const(*case));
                self.wfunc.instruction(&W::I64Eq);
                self.wfunc.instruction(&W::Select);
                self.wfunc.instruction(&W::LocalSet(pc));
            }
            self.wfunc.instruction(&W::Br(cont));
        }
        Terminator::Unreachable => {
            self.wfunc.instruction(&W::Unreachable);
        }
    }
    Ok(())
}

fn emit_call(&mut self, func: &str, args: &[Operand]) -> Result<(), WasmCodegenError> {
    // -------------------------------------------------------------
    // Built-in: println / print
    // -------------------------------------------------------------
    if func == "println" || func == "print" {
        if args.len() == 1 {
            let ty = self.operand_ty(&args[0]).unwrap_or(MirType::I64);
            match (&args[0], &ty) {
                // String constant: emit (offset,len) directly, no unpack.
                (Operand::Constant(Constant::Str(s)), _) => {
                    let (offset, len) = self.cg.intern_string(s);
                    self.wfunc.instruction(&W::I32Const(offset as i32));
                    self.wfunc.instruction(&W::I32Const(len as i32));
                    self.wfunc.instruction(&W::Call(self.cg.print_str_idx));
                    return Ok(());
                }
                // String-typed local (or any string operand): unpack the
                // packed i64 into (offset, len) then call print_str.
                (op, MirType::Str) => {
                    self.emit_operand(op)?;
                    self.emit_unpack_string();
                    self.wfunc.instruction(&W::Call(self.cg.print_str_idx));
                    return Ok(());
                }
                // Float-typed operand: print as f64.
                (op, MirType::F64) | (op, MirType::F32) => {
                    self.emit_operand(op)?;
                    if matches!(ty, MirType::F32) {
                        self.wfunc.instruction(&W::F64PromoteF32);
                    }
                    self.wfunc.instruction(&W::Call(self.cg.print_f64_idx));
                    return Ok(());
                }
                // Bool: print true/false, not the raw 0/1 encoding
                // (mirrors the to_string builtin's bool arm).
                (op, MirType::Bool) => {
                    let op = op.clone();
                    self.emit_to_str_packed(&op)?;
                    self.emit_unpack_string();
                    self.wfunc.instruction(&W::Call(self.cg.print_str_idx));
                    return Ok(());
                }
                // Default: print as i64.
                (op, _) => {
                    self.emit_operand(op)?;
                    self.wfunc.instruction(&W::Call(self.cg.print_i64_idx));
                    return Ok(());
                }
            }
        }
        return Err(WasmCodegenError::unsupported(
            "println with multiple arguments (concat strings with `str_concat` first)",
        ));
    }

    // -------------------------------------------------------------
    // Built-in: len(s/arr) — string or array length
    // Strings: high 32 bits of packed i64 (offset|len encoding).
    // Arrays: opaque i64 handles — call host kryos_array_length.
    // -------------------------------------------------------------
    if func == "len" && args.len() == 1 {
        let ty = self.operand_ty(&args[0]).unwrap_or(MirType::Str);
        self.emit_operand(&args[0])?;
        match ty {
            MirType::Array(_, _) => {
                let idx = self.cg.array_length_idx;
                self.wfunc.instruction(&W::Call(idx));
                self.wfunc.instruction(&W::I64ExtendI32U);
            }
            MirType::Map { .. } => {
                self.wfunc.instruction(&W::Call(self.cg.map_len_idx));
                self.wfunc.instruction(&W::I64ExtendI32U);
            }
            _ => {
                self.wfunc.instruction(&W::I64Const(32));
                self.wfunc.instruction(&W::I64ShrU);
            }
        }
        return Ok(());
    }

    // -------------------------------------------------------------
    // Built-in: str_concat(a, b) — concatenate two strings
    // -------------------------------------------------------------
    if func == "str_concat" && args.len() == 2 {
        // Push (off1, len1, off2, len2) by unpacking each packed i64.
        // We have one scratch i64 local; reuse it sequentially.
        for arg in args {
            self.emit_operand(arg)?;

        self.emit_unpack_string();
    }
    self.wfunc.instruction(&W::Call(self.cg.string_concat_idx));
    return Ok(());
}

// -------------------------------------------------------------
// Built-in: array_new(count) — allocate i64 array of given size
// -------------------------------------------------------------
if func == "array_new" && args.len() == 1 {
    self.emit_operand(&args[0])?;
    self.wfunc.instruction(&W::I32WrapI64);
    self.wfunc.instruction(&W::Call(self.cg.array_new_idx));
    return Ok(());
}

// -------------------------------------------------------------
// Built-in: array_get(arr, idx) -> i64
// -------------------------------------------------------------
if func == "array_get" && args.len() == 2 {
    self.emit_operand(&args[0])?;            // packed i64 array
    self.emit_operand(&args[1])?;            // index i64
    self.wfunc.instruction(&W::I32WrapI64);  // -> i32 index
    self.wfunc.instruction(&W::Call(self.cg.array_get_idx));
    return Ok(());
}

// -------------------------------------------------------------
// Built-in: array_set(arr, idx, value)
// -------------------------------------------------------------
if func == "array_set" && args.len() == 3 {
    self.emit_operand(&args[0])?;            // packed i64 array
    self.emit_operand(&args[1])?;            // index i64
    self.wfunc.instruction(&W::I32WrapI64);  // -> i32 index
    self.emit_operand(&args[2])?;            // value i64
    self.wfunc.instruction(&W::Call(self.cg.array_set_idx));
    return Ok(());
}

// -------------------------------------------------------------
// WASM v0.4 web builtins — DOM / canvas / fetch / alert
//   dom_set_text(id: str, text: str)
//   dom_get_value(id: str) -> str
//   alert(msg: str)
//   canvas_fill_rect(canvas_id, x, y, w, h, color)
//   canvas_clear(canvas_id)
//   fetch_text(url: str) -> str
// -------------------------------------------------------------
if func == "dom_set_text" && args.len() == 2 {
    self.emit_operand(&args[0])?; self.emit_unpack_string();
    self.emit_operand(&args[1])?; self.emit_unpack_string();
    self.wfunc.instruction(&W::Call(self.cg.dom_set_text_idx));
    return Ok(());
}
if func == "dom_get_value" && args.len() == 1 {
    self.emit_operand(&args[0])?; self.emit_unpack_string();
    self.wfunc.instruction(&W::Call(self.cg.dom_get_value_idx));
    return Ok(());
}
if func == "alert" && args.len() == 1 {
    self.emit_operand(&args[0])?; self.emit_unpack_string();
    self.wfunc.instruction(&W::Call(self.cg.alert_idx));
    return Ok(());
}
if func == "canvas_fill_rect" && args.len() == 6 {
    self.emit_operand(&args[0])?; self.emit_unpack_string();  // id off,len
    self.emit_operand(&args[1])?;                              // x i64
    self.emit_operand(&args[2])?;                              // y i64
    self.emit_operand(&args[3])?;                              // w i64
    self.emit_operand(&args[4])?;                              // h i64
    self.emit_operand(&args[5])?; self.emit_unpack_string();   // color off,len
    self.wfunc.instruction(&W::Call(self.cg.canvas_fill_rect_idx));
    return Ok(());
}
if func == "canvas_clear" && args.len() == 1 {
    self.emit_operand(&args[0])?; self.emit_unpack_string();
    self.wfunc.instruction(&W::Call(self.cg.canvas_clear_idx));
    return Ok(());
}
if func == "fetch_text" && args.len() == 1 {
    self.emit_operand(&args[0])?; self.emit_unpack_string();
    self.wfunc.instruction(&W::Call(self.cg.fetch_text_idx));
    return Ok(());
}

// -------------------------------------------------------------
// Built-in: to_string(v) — convert i64/bool/f64 to decimal string
// -------------------------------------------------------------
if func == "to_string" && args.len() == 1 {
    let ty = self.operand_ty(&args[0]).unwrap_or(MirType::I64);
    self.emit_operand(&args[0])?;
    match ty {
        MirType::F64 => {
            self.wfunc.instruction(&W::Call(self.cg.to_string_f64_idx));
        }
        MirType::F32 => {
            self.wfunc.instruction(&W::F64PromoteF32);
            self.wfunc.instruction(&W::Call(self.cg.to_string_f64_idx));
        }
        MirType::Bool => {
            // "true"/"false", NOT the raw i64 encoding -- falling
            // through to to_string_i64 silently printed 1/0 for every
            // bool from ordinary function logic (native backends print
            // the words). Bools here are i64 0/1; eqz gives an i32
            // cond (1 when false), so the If yields the packed str.
            let (t_off, t_len) = self.cg.intern_string("true");
            let (f_off, f_len) = self.cg.intern_string("false");
            let t_packed = (((t_len as u64) << 32) | (t_off as u64)) as i64;
            let f_packed = (((f_len as u64) << 32) | (f_off as u64)) as i64;
            self.wfunc.instruction(&W::I64Eqz);
            self.wfunc.instruction(&W::If(BlockType::Result(ValType::I64)));
            self.wfunc.instruction(&W::I64Const(f_packed));
            self.wfunc.instruction(&W::Else);
            self.wfunc.instruction(&W::I64Const(t_packed));
            self.wfunc.instruction(&W::End);
        }
        _ => {
            self.wfunc.instruction(&W::Call(self.cg.to_string_i64_idx));
        }
    }
    return Ok(());
}

// -------------------------------------------------------------
// Built-in: parse_int(s) / parse_float(s) — string -> number
// -------------------------------------------------------------
if func == "parse_int" && args.len() == 1 {
    self.emit_operand(&args[0])?;
    self.wfunc.instruction(&W::Call(self.cg.string_parse_int_idx));
    return Ok(());
}
if func == "parse_float" && args.len() == 1 {
    self.emit_operand(&args[0])?;
    self.wfunc.instruction(&W::Call(self.cg.string_parse_float_idx));
    return Ok(());
}

// -------------------------------------------------------------
// Built-in: push(arr, value) — append value to array, return new handle
// -------------------------------------------------------------
if func == "push" && args.len() == 2 {
    self.emit_operand(&args[0])?; // array handle
    self.emit_operand(&args[1])?; // value i64
    self.wfunc.instruction(&W::Call(self.cg.array_push_idx));
    return Ok(());
}

// Built-in: pop(arr) -> element (removes + returns the last element).
if func == "pop" && args.len() == 1 {
    self.emit_operand(&args[0])?; // array handle
    self.wfunc.instruction(&W::Call(self.cg.array_pop_idx));
    return Ok(());
}

// -------------------------------------------------------------
// Built-in: substr(s, start, end) — byte-indexed substring
// Lowered to kryos_string_slice(packed, start_i32, end_i32).
// -------------------------------------------------------------
if func == "substr" && args.len() == 3 {
    self.emit_operand(&args[0])?;           // packed str i64
    self.emit_operand(&args[1])?;           // start i64
    self.wfunc.instruction(&W::I32WrapI64); // -> i32
    self.emit_operand(&args[2])?;           // end i64
    self.wfunc.instruction(&W::I32WrapI64); // -> i32
    self.wfunc.instruction(&W::Call(self.cg.string_slice_idx));
    return Ok(());
}

// -------------------------------------------------------------
// Built-in: char_code(s) -> i64 — byte value of first character
// -------------------------------------------------------------
if func == "char_code" && args.len() == 1 {
    self.emit_operand(&args[0])?; // packed str i64
    self.wfunc.instruction(&W::Call(self.cg.string_char_code_idx));
    return Ok(());
}

// -------------------------------------------------------------
// Built-in: contains(haystack, needle) -> bool (for str args)
// -------------------------------------------------------------
if func == "contains" && args.len() == 2 {
    let ty = self.operand_ty(&args[0]).unwrap_or(MirType::I64);
    if matches!(ty, MirType::Str) {
        self.emit_operand(&args[0])?; // packed haystack i64
        self.emit_operand(&args[1])?; // packed needle i64
        self.wfunc.instruction(&W::Call(self.cg.string_contains_idx));
        return Ok(());
    }
}

// -------------------------------------------------------------
// Runtime ARC: kryos_string_retain(packed) -> packed (no-op in WASM)
// -------------------------------------------------------------
if func == "kryos_string_retain" && args.len() == 1 {
    self.emit_operand(&args[0])?;
    self.wfunc.instruction(&W::Call(self.cg.string_retain_idx));
    return Ok(());
}

// -------------------------------------------------------------
// Runtime ARC: *_retain_opt(handle) -> handle. Emitted by the
// share-retain lowering (container let-bindings, map/array value
// stores, push of a container element). v0.1 WASM has no
// refcounted heap, so these are pure identity — emit the operand
// as the result, no host import required.
// -------------------------------------------------------------
if (func == "kryos_string_retain_opt"
    || func == "kryos_array_retain_opt"
    || func == "kryos_map_retain_opt")
    && args.len() == 1
{
    self.emit_operand(&args[0])?;
    return Ok(());
}

// -------------------------------------------------------------
// Runtime: kryos_string_char_at(packed, idx) -> packed single-char str
// -------------------------------------------------------------
if func == "kryos_string_char_at" && args.len() == 2 {
    self.emit_operand(&args[0])?; // packed str i64
    self.emit_operand(&args[1])?; // idx i64
    self.wfunc.instruction(&W::Call(self.cg.string_char_at_idx));
    return Ok(());
}

// -------------------------------------------------------------
// Reassignment releases (native leak fix): wasm memory is host-
// managed, so these are no-ops here -- evaluate to 0 like the
// native helpers' i64 return. Wasm-side reclamation is tracked
// separately in docs/wasm-contract.md.
// -------------------------------------------------------------
if matches!(
    func,
    "kryos_string_release_if_ne"
        | "kryos_array_release_if_ne"
        | "kryos_map_release_if_ne"
) && args.len() == 2
{
    self.wfunc.instruction(&W::I64Const(0));
    return Ok(());
}

// -------------------------------------------------------------
// Map runtime builtins (str-keyed). The MIR lowers `m[k]=v` / `m[k]` /
// `contains(m,k)` to these; the host keeps a JS Map per handle.
// -------------------------------------------------------------
if (func == "kryos_map_insert_str" || func == "map_insert_str") && args.len() == 3 {
    self.emit_operand(&args[0])?; // handle
    self.emit_operand(&args[1])?; // packed key
    self.emit_operand(&args[2])?; // value
    self.wfunc.instruction(&W::Call(self.cg.map_insert_str_idx));
    return Ok(());
}
if (func == "kryos_map_get_str" || func == "map_get_str") && args.len() == 2 {
    self.emit_operand(&args[0])?;
    self.emit_operand(&args[1])?;
    self.wfunc.instruction(&W::Call(self.cg.map_get_str_idx));
    return Ok(());
}
if (func == "kryos_map_has_str" || func == "map_has_str") && args.len() == 2 {
    self.emit_operand(&args[0])?;
    self.emit_operand(&args[1])?;
    self.wfunc.instruction(&W::Call(self.cg.map_has_str_idx));
    return Ok(());
}
// Integer-keyed map family (map<i64, V> lowers to these runtime names).
if (func == "kryos_map_insert" || func == "map_insert") && args.len() == 3 {
    self.emit_operand(&args[0])?; // handle
    self.emit_operand(&args[1])?; // i64 key
    self.emit_operand(&args[2])?; // value
    self.wfunc.instruction(&W::Call(self.cg.map_insert_idx));
    return Ok(());
}
if (func == "kryos_map_get" || func == "map_get") && args.len() == 2 {
    self.emit_operand(&args[0])?;
    self.emit_operand(&args[1])?;
    self.wfunc.instruction(&W::Call(self.cg.map_get_idx));
    return Ok(());
}
if (func == "kryos_map_has" || func == "map_has") && args.len() == 2 {
    self.emit_operand(&args[0])?;
    self.emit_operand(&args[1])?;
    self.wfunc.instruction(&W::Call(self.cg.map_has_idx));
    return Ok(());
}
// Ownership deep-copy marker for an enum value pulled out of a still-
// owned container. It exists to prevent aliased ARC drops on the
// NATIVE backends; the wasm host never frees (values live in JS-side
// arenas with no refcounting) and the supported wasm subset has no
// in-place enum-payload mutation, so identity is semantically exact
// here. (The struct sibling __kryos_struct_index_clone is NOT mapped:
// structs are field-mutable in the subset, so identity would alias.)
if func == "__kryos_enum_index_clone" && args.len() == 1 {
    self.emit_operand(&args[0])?;
    return Ok(());
}
// Struct deep-clone marker: on the native backends `let copy = s`
// (struct) clones heap fields so both bindings own independent
// references (docs/06-ownership.md). The wasm host never frees, so
// identity carries no drop-balance hazard here -- it preserves the

    // wasm backend's existing alias behavior for struct copies exactly.
    // (Divergence note: an in-place mutation through the copy is visible
    // to the source on wasm but not on native; the documented native
    // semantics are authoritative.)
    if func == "__kryos_struct_index_clone" && args.len() == 1 {
        self.emit_operand(&args[0])?;
        return Ok(());
    }
    if (func == "kryos_map_new" || func == "map_new") && args.is_empty() {
        self.wfunc.instruction(&W::Call(self.cg.map_new_idx));
        return Ok(());
    }

    // -------------------------------------------------------------
    // User function call
    // -------------------------------------------------------------
    if let Some(&idx) = self.cg.fn_indices.get(func) {
        for a in args {
            self.emit_operand(a)?;
        }
        self.wfunc.instruction(&W::Call(idx));
        Ok(())
    } else {
        Err(WasmCodegenError::unsupported(&format!(
            "call to `{func}` — supported builtins: println, len, str_concat, array_new/get/set, to_string"
        )))
    }
}

/// Emit f64 binary operations.
fn emit_binop_f64(&mut self, op: MirBinOp) -> Result<(), WasmCodegenError> {
    match op {
        MirBinOp::Add => { self.wfunc.instruction(&W::F64Add); }
        MirBinOp::Sub => { self.wfunc.instruction(&W::F64Sub); }
        MirBinOp::Mul => { self.wfunc.instruction(&W::F64Mul); }
        MirBinOp::Div => { self.wfunc.instruction(&W::F64Div); }
        MirBinOp::Eq  => { self.wfunc.instruction(&W::F64Eq);  self.wfunc.instruction(&W::I64ExtendI32U); }
        MirBinOp::Neq => { self.wfunc.instruction(&W::F64Ne);  self.wfunc.instruction(&W::I64ExtendI32U); }
        MirBinOp::Lt  => { self.wfunc.instruction(&W::F64Lt);  self.wfunc.instruction(&W::I64ExtendI32U); }
        MirBinOp::Gt  => { self.wfunc.instruction(&W::F64Gt);  self.wfunc.instruction(&W::I64ExtendI32U); }
        MirBinOp::LtEq => { self.wfunc.instruction(&W::F64Le); self.wfunc.instruction(&W::I64ExtendI32U); }
        MirBinOp::GtEq => { self.wfunc.instruction(&W::F64Ge); self.wfunc.instruction(&W::I64ExtendI32U); }
        other => {
            return Err(WasmCodegenError::unsupported(&format!(
                "f64 binary op `{other:?}`"
            )));
        }
    }
    Ok(())
}

/// Emit an operand as a packed str i64 (calling to_string if the type is not Str).
fn emit_to_str_packed(&mut self, op: &Operand) -> Result<(), WasmCodegenError> {
    let ty = self.operand_ty(op).unwrap_or(MirType::I64);
    self.emit_operand(op)?;
    match ty {
        MirType::Str => { /* already packed str */ }
        MirType::F64 => {
            self.wfunc.instruction(&W::Call(self.cg.to_string_f64_idx));
        }
        MirType::F32 => {
            self.wfunc.instruction(&W::F64PromoteF32);
            self.wfunc.instruction(&W::Call(self.cg.to_string_f64_idx));
        }
        MirType::Bool => {
            // Same true/false rendering as the to_string builtin -- a bool
            // in interpolation/println otherwise printed its raw 0/1.
            let (t_off, t_len) = self.cg.intern_string("true");
            let (f_off, f_len) = self.cg.intern_string("false");
            let t_packed = (((t_len as u64) << 32) | (t_off as u64)) as i64;
            let f_packed = (((f_len as u64) << 32) | (f_off as u64)) as i64;
            self.wfunc.instruction(&W::I64Eqz);
            self.wfunc.instruction(&W::If(BlockType::Result(ValType::I64)));
            self.wfunc.instruction(&W::I64Const(f_packed));
            self.wfunc.instruction(&W::Else);
            self.wfunc.instruction(&W::I64Const(t_packed));
            self.wfunc.instruction(&W::End);
        }
        _ => {
            self.wfunc.instruction(&W::Call(self.cg.to_string_i64_idx));
        }
    }
    Ok(())
}

/// Emit a StringConcat rvalue (string interpolation: N parts → pairwise concat).
fn emit_string_concat(&mut self, parts: &[Operand]) -> Result<(), WasmCodegenError> {
    if parts.is_empty() {
        let (off, len) = self.cg.intern_string("");
        let packed = ((len as u64) << 32) | (off as u64);
        self.wfunc.instruction(&W::I64Const(packed as i64));
        return Ok(());
    }
    if parts.len() == 1 {
        return self.emit_to_str_packed(&parts[0]);
    }
    // Pairwise left-fold: acc = concat(p0, p1); for p in p2..: acc = concat(acc, p)
    self.emit_to_str_packed(&parts[0])?;
    self.emit_unpack_string();
    self.emit_to_str_packed(&parts[1])?;
    self.emit_unpack_string();
    self.wfunc.instruction(&W::Call(self.cg.string_concat_idx));
    for part in &parts[2..] {
        // Stack: [packed_acc]
        self.emit_unpack_string();              // [off_acc, len_acc]
        self.emit_to_str_packed(part)?;         // [off_acc, len_acc, packed_next]
        self.emit_unpack_string();              // [off_acc, len_acc, off_next, len_next]
        self.wfunc.instruction(&W::Call(self.cg.string_concat_idx));
    }
    Ok(())
}

/// Emit a Switch terminator as a flat chain of `if` blocks.
fn emit_switch(
    &mut self,
    value: Operand,
    targets: Vec<(i64, BlockId)>,
    default: BlockId,
) -> Result<(), WasmCodegenError> {
    // Collect unique arm blocks in order of first appearance, grouping
    // values that map to the same block (or-patterns: 1|2|3 => ...).
    let mut seen_ids: Vec<u32> = Vec::new();
    let mut block_vals: HashMap<u32, (BlockId, Vec<i64>)> = HashMap::new();
    for (val, bid) in &targets {
        if let Some(entry) = block_vals.get_mut(&bid.0) {
            entry.1.push(*val);
        } else {
            seen_ids.push(bid.0);
            block_vals.insert(bid.0, (*bid, vec![*val]));
        }
    }

    // Detect whether any arm Goto's a join block (vs returning directly).
    let join = self.find_switch_join(&targets, default);

    // Wrap in a block so Goto(join) arms can break out with `br 1`.
    if join.is_some() {
        self.wfunc.instruction(&W::Block(BlockType::Empty));
    }

    // Emit one `if` block per unique arm.
    for &bid_u32 in &seen_ids {
        let (bid, vals) = &block_vals[&bid_u32];
        self.emit_switch_cond(&value, vals)?;
        self.wfunc.instruction(&W::If(BlockType::Empty));
        let arm_idx = self.block_index(*bid)?;
        if !self.visited[arm_idx] {
            self.visited[arm_idx] = true;
            let instrs: Vec<_> = self.func.blocks[arm_idx].instructions.clone();
            for inst in &instrs {
                self.emit_instruction(inst)?;
            }
            let term = self.func.blocks[arm_idx].terminator.clone();
            self.emit_switch_arm_term(&term, join)?;
        }
        self.wfunc.instruction(&W::End);
    }

    // Emit the default arm (always reached if no earlier arm matched).
    let default_idx = self.block_index(default)?;
    if !self.visited[default_idx] {
        self.visited[default_idx] = true;
        let instrs: Vec<_> = self.func.blocks[default_idx].instructions.clone();
        for inst in &instrs {
            self.emit_instruction(inst)?;
        }
        let term = self.func.blocks[default_idx].terminator.clone();
        // Default arm is at depth 0 inside the wrapper block (no nested if),
        // so Goto(join) just falls through to the wrapper `end`.
        match term {
            Terminator::Return(ref v) => {
                if let Some(op) = v.as_ref() {
                    self.emit_operand(op)?;
                }
                self.wfunc.instruction(&W::Return);
            }
            Terminator::Goto(j) if Some(j) == join => { /* fall through */ }
            Terminator::Goto(j) => { self.emit_block(j)?; }
            Terminator::Branch { ref cond, then_block, else_block } => {
                self.emit_if_else(cond, then_block, else_block)?;
            }
            Terminator::Switch { value, targets, default: def } => {
                self.emit_switch(value, targets, def)?;
            }
            Terminator::Unreachable => { self.wfunc.instruction(&W::Unreachable); }
        }
    }

    if join.is_some() {
        self.wfunc.instruction(&W::End); // end wrapper block
    }

    if let Some(j) = join {
        self.emit_block(j)?;
    }
    Ok(())
}

/// Emit the terminator for a non-default switch arm (inside an `if` block).
fn emit_switch_arm_term(&mut self, term: &Terminator, join: Option<BlockId>) -> Result<(), WasmCodegenError> {
    match term {
        Terminator::Return(ref v) => {
            if let Some(op) = v.as_ref() {
                self.emit_operand(op)?;
            }
            self.wfunc.instruction(&W::Return);
        }
        Terminator::Goto(j) if Some(*j) == join => {
            // Break out of: if (depth 0) + wrapper block (depth 1).
            self.wfunc.instruction(&W::Br(1));
        }
        Terminator::Goto(j) => {
            // Arm continues into a nested block (e.g. match arm with inner if).
            self.emit_block(*j)?;
        }
        Terminator::Branch { ref cond, then_block, else_block } => {
            self.emit_if_else(cond, *then_block, *else_block)?;
        }
        Terminator::Switch { value, targets, default } => {
            self.emit_switch(value.clone(), targets.clone(), *default)?;
        }
        Terminator::Unreachable => { self.wfunc.instruction(&W::Unreachable); }
    }
    Ok(())
}

/// Emit the condition for a switch arm: value == vals[0] || value == vals[1] || ...
/// Leaves an i32 (0/1) on the stack (WASM comparison ops return i32).
fn emit_switch_cond(&mut self, value: &Operand, vals: &[i64]) -> Result<(), WasmCodegenError> {
    self.emit_operand(value)?;
    self.wfunc.instruction(&W::I64Const(vals[0]));
    self.wfunc.instruction(&W::I64Eq);
    for &v in &vals[1..] {
        self.emit_operand(value)?;
        self.wfunc.instruction(&W::I64Const(v));
        self.wfunc.instruction(&W::I64Eq);
        self.wfunc.instruction(&W::I32Or);
    }
    Ok(())
}

/// Return the join block for a switch: the block that all arms Goto, if any.
fn find_switch_join(&self, targets: &[(i64, BlockId)], default: BlockId) -> Option<BlockId> {
    let default_idx = *self.id_to_index.get(&default.0)?;
    if let Terminator::Goto(j) = self.func.blocks[default_idx].terminator {
        return Some(j);
    }
    for (_, bid) in targets {
        let idx = *self.id_to_index.get(&bid.0)?;
        if let Terminator::Goto(j) = self.func.blocks[idx].terminator {
            return Some(j);
        }
    }
    None
}

fn emit_cast(&mut self, ty: &MirType) -> Result<(), WasmCodegenError> {
    match ty {
        MirType::I64 | MirType::U64 | MirType::Bool => {
            // No-op (already i64).
        }
        MirType::F64 => {
            self.wfunc.instruction(&W::F64ConvertI64S);
        }
        MirType::I32 => {
            self.wfunc.instruction(&W::I32WrapI64);
            self.wfunc.instruction(&W::I64ExtendI32S);
        }
        // Narrow ints are uniform i64 slots in wasm (like native), so these
        // casts truncate/sign-extend within i64. char = Unicode scalar (u32).
        MirType::U32 | MirType::Char => {
            self.wfunc.instruction(&W::I64Const(0xFFFF_FFFF));
            self.wfunc.instruction(&W::I64And);
        }
        MirType::U8 => {
            self.wfunc.instruction(&W::I64Const(0xFF));
            self.wfunc.instruction(&W::I64And);
        }
        MirType::U16 => {
            self.wfunc.instruction(&W::I64Const(0xFFFF));
            self.wfunc.instruction(&W::I64And);
        }
        MirType::I8 => {
            self.wfunc.instruction(&W::I64Const(56));
            self.wfunc.instruction(&W::I64Shl);
            self.wfunc.instruction(&W::I64Const(56));
            self.wfunc.instruction(&W::I64ShrS);
        }
        MirType::I16 => {
            self.wfunc.instruction(&W::I64Const(48));
            self.wfunc.instruction(&W::I64Shl);
            self.wfunc.instruction(&W::I64Const(48));
            self.wfunc.instruction(&W::I64ShrS);
        }
        _ => {
            return Err(WasmCodegenError::unsupported(&format!(
                "cast to type `{ty}`"
            )));
        }
    }

        Ok(())
    }
}

