fn fmt_fn_signature_multiline(
    &mut self,
    name: &str,
    generics: &[GenericParam],
    params: &[Param],
    ret_ty: &Option<TypeExpr>,
    public: bool,
) {
    if public {
        self.write("pub ");
    }
    self.write("fn ");
    self.write(name);
    self.fmt_generics(generics);
    self.writeln("(");
    self.push_indent();
    for (i, p) in params.iter().enumerate() {
        self.write_indent();
        self.write(&self.fmt_param_to_string(p));
        if i + 1 < params.len() {
            self.write(",");
        }
        self.newline();
    }
    self.pop_indent();
    self.write_indent();
    self.write(")");
    if let Some(ty) = ret_ty {
        self.write(" -> ");
        self.write(&self.fmt_type_to_string(ty));
    }
}

fn fmt_param_to_string(&self, param: &Param) -> String {
    let mut s = param.name.clone();
    if let Some(ty) = &param.ty {
        s.push_str(": ");
        s.push_str(&self.fmt_type_to_string(ty));
    }
    if let Some(default) = &param.default {
        s.push_str(" = ");
        s.push_str(&self.fmt_expr_to_string(default));
    }
    s
}

// -- struct -------------------------------------------------------------

fn fmt_struct(
    &mut self,
    name: &str,
    generics: &[GenericParam],
    fields: &[StructField],
    public: bool,
    annotations: &[Annotation],
) {
    self.fmt_annotations(annotations);
    self.write_indent();
    if public {
        self.write("pub ");
    }
    self.write("struct ");
    self.write(name);
    self.fmt_generics(generics);
    self.writeln(" {");
    self.push_indent();
    for field in fields {
        self.write_indent();
        if field.public {
            self.write("pub ");
        }
        self.write(&field.name);
        self.write(": ");
        self.write(&self.fmt_type_to_string(&field.ty));
        if let Some(default) = &field.default {
            self.write(" = ");
            self.write(&self.fmt_expr_to_string(default));
        }
        self.newline();
    }
    self.pop_indent();
    self.write_indent();
    self.writeln("}");
}

// -- enum ---------------------------------------------------------------

fn fmt_enum(
    &mut self,
    name: &str,
    generics: &[GenericParam],
    variants: &[EnumVariant],
    public: bool,
    annotations: &[Annotation],
) {
    self.fmt_annotations(annotations);
    self.write_indent();
    if public {
        self.write("pub ");
    }
    self.write("enum ");
    self.write(name);
    self.fmt_generics(generics);
    self.writeln(" {");
    self.push_indent();
    for variant in variants {
        self.write_indent();
        self.write(&variant.name);
        if !variant.fields.is_empty() {
            self.write("(");
            for (i, ty) in variant.fields.iter().enumerate() {
                if i > 0 {
                    self.write(", ");
                }
                self.write(&self.fmt_type_to_string(ty));
            }
            self.write(")");
        }
        self.newline();
    }
    self.pop_indent();
    self.write_indent();
    self.writeln("}");
}

// -- trait --------------------------------------------------------------

fn fmt_trait(&mut self, name: &str, generics: &[GenericParam], methods: &[Decl], public: bool) {
    self.write_indent();
    if public {
        self.write("pub ");
    }
    self.write("trait ");
    self.write(name);
    self.fmt_generics(generics);
    self.writeln(" {");
    self.push_indent();
    for (i, method) in methods.iter().enumerate() {
        if i > 0 {
            self.newline();
        }
        self.fmt_decl(method);
    }
    self.pop_indent();
    self.write_indent();
    self.writeln("}");
}

// -- impl ---------------------------------------------------------------

fn fmt_impl(
    &mut self,
    target: &str,
    trait_name: &Option<String>,
    generics: &[GenericParam],
    methods: &[Decl],
) {
    self.write_indent();
    self.write("impl");
    self.fmt_generics(generics);
    self.write(" ");
    if let Some(tn) = trait_name {
        self.write(tn);
        self.write(" for ");
    }
    self.write(target);
    self.writeln(" {");
    self.push_indent();
    for (i, method) in methods.iter().enumerate() {
        if i > 0 {
            self.newline();
        }
        self.fmt_decl(method);
    }
    self.pop_indent();
    self.write_indent();
    self.writeln("}");
}

// -- actor --------------------------------------------------------------

fn fmt_actor(
    &mut self,
    name: &str,
    state_fields: &[StructField],
    handlers: &[MessageHandler],
    annotations: &[Annotation],
) {
    self.fmt_annotations(annotations);
    self.write_indent();
    self.write("actor ");
    self.write(name);
    self.writeln(" {");
    self.push_indent();

    // State fields
    for field in state_fields {
        self.write_indent();
        if field.public {
            self.write("pub ");
        }
        self.write(&field.name);
        self.write(": ");
        self.write(&self.fmt_type_to_string(&field.ty));
        if let Some(default) = &field.default {
            self.write(" = ");
            self.write(&self.fmt_expr_to_string(default));
        }
        self.newline();
    }

    // Blank line between state and handlers, if both are non-empty
    if !state_fields.is_empty() && !handlers.is_empty() {
        self.newline();
    }

    // Handlers
    for (i, handler) in handlers.iter().enumerate() {
        if i > 0 {
            self.newline();
        }
        self.write_indent();
        self.write("fn ");
        self.write(&handler.name);
        self.write("(");
        for (j, p) in handler.params.iter().enumerate() {
            if j > 0 {
                self.write(", ");
            }
            self.write(&self.fmt_param_to_string(p));
        }
        self.write(")");
        if let Some(ty) = &handler.ret_ty {
            self.write(" -> ");
            self.write(&self.fmt_type_to_string(ty));
        }
        self.writeln(" {");
        self.fmt_block_body(&handler.body);
        self.write_indent();
        self.writeln("}");
    }

    self.pop_indent();
    self.write_indent();
    self.writeln("}");
}

// -- type alias ---------------------------------------------------------

fn fmt_type_alias(
    &mut self,
    name: &str,
    generics: &[GenericParam],
    ty: &TypeExpr,
    public: bool,
) {
    self.write_indent();
    if public {
        self.write("pub ");
    }
    self.write("type ");
    self.write(name);
    self.fmt_generics(generics);
    self.write(" = ");
    self.write(&self.fmt_type_to_string(ty));
    self.newline();
}

// -- const --------------------------------------------------------------

fn fmt_const(&mut self, name: &str, ty: &Option<TypeExpr>, value: &Expr, public: bool) {
    self.write_indent();
    if public {
        self.write("pub ");
    }
    self.write("let ");
    self.write(name);

    if let Some(ty_expr) = ty {
        self.write(": ");
        self.write(&self.fmt_type_to_string(ty_expr));
    }
    self.write(" = ");
    self.write(&self.fmt_expr_to_string(value));
    self.newline();
}

// -- import -------------------------------------------------------------

fn fmt_import(&mut self, path: &ImportPath) {
    self.write_indent();
    self.write("use ");
    self.write(&path.segments.join("::"));
    if !path.items.is_empty() {
        self.write("::{");
        self.write(&path.items.join(", "));
        self.write("}");
    }
    if let Some(alias) = &path.alias {
        self.write(" as ");
        self.write(alias);
    }
    self.newline();
}

// -- extern -------------------------------------------------------------

fn fmt_extern(&mut self, abi: &str, items: &[Decl]) {
    self.write_indent();
    self.write("extern \"");
    self.write(abi);
    self.write("\" ");
    self.writeln("{");
    self.push_indent();
    for item in items {
        self.fmt_decl(item);
    }
    self.pop_indent();
    self.write_indent();
    self.writeln("}");
}

// -----------------------------------------------------------------------
// Statements
// -----------------------------------------------------------------------

fn fmt_block_body(&mut self, block: &Block) {
    self.push_indent();
    for stmt in &block.stmts {
        self.fmt_stmt(stmt);
    }
    self.pop_indent();
}

fn fmt_stmt(&mut self, stmt: &Stmt) {
    match stmt {
        Stmt::Let {
            name,
            mutable,
            ty,
            value,
            pattern,
            ..
        } => {
            self.write_indent();
            self.write("let ");
            if *mutable {
                self.write("mut ");
            }
            if let Some(pat) = pattern {
                self.write(&self.fmt_pattern_to_string(pat));
            } else {
                self.write(name);
            }
            if let Some(ty) = ty {
                self.write(": ");
                self.write(&self.fmt_type_to_string(ty));
            }
            if let Some(val) = value {
                self.write(" = ");
                self.write(&self.fmt_expr_to_string(val));
            }
            self.newline();
        }

        Stmt::Assign {
            target, op, value, ..
        } => {
            self.write_indent();
            self.write(&self.fmt_expr_to_string(target));
            self.write(" ");
            self.write(match op {
                AssignOp::Assign => "=",
                AssignOp::AddAssign => "+=",
                AssignOp::SubAssign => "-=",
                AssignOp::MulAssign => "*=",
                AssignOp::DivAssign => "/=",
                AssignOp::ModAssign => "%=",
            });
            self.write(" ");
            self.write(&self.fmt_expr_to_string(value));
            self.newline();
        }

        Stmt::Return { value, .. } => {
            self.write_indent();
            self.write("return");
            if let Some(val) = value {
                self.write(" ");
                self.write(&self.fmt_expr_to_string(val));
            }
            self.newline();
        }

        Stmt::If {
            condition,
            then_block,
            elif_clauses,
            else_block,
            ..
        } => {
            self.write_indent();
            self.write("if ");
            self.write(&self.fmt_expr_to_string(condition));
            self.writeln(" {");
            self.fmt_block_body(then_block);
            self.write_indent();
            self.write("}");

            for (cond, block) in elif_clauses {
                self.write(" elif ");
                self.write(&self.fmt_expr_to_string(cond));
                self.writeln(" {");
                self.fmt_block_body(block);
                self.write_indent();
                self.write("}");
            }

            if let Some(else_blk) = else_block {
                self.writeln(" else {");
                self.fmt_block_body(else_blk);
                self.write_indent();
                self.writeln("}");
            } else {
                self.newline();
            }
        }

        Stmt::For {
            parallel,
            pattern,
            iterable,
            body,
            ..
        } => {
            self.write_indent();
            if *parallel {
                self.write("parallel ");
            }
            self.write("for ");
            self.write(&self.fmt_pattern_to_string(pattern));
            self.write(" in ");
            self.write(&self.fmt_expr_to_string(iterable));
            self.writeln(" {");
            self.fmt_block_body(body);
            self.write_indent();
            self.writeln("}");
        }

        Stmt::While {
            condition, body, ..
        } => {
            self.write_indent();
            self.write("while ");
            self.write(&self.fmt_expr_to_string(condition));
            self.writeln(" {");
            self.fmt_block_body(body);
            self.write_indent();
            self.writeln("}");
        }

        Stmt::DenyBlock { denied, body, .. } => {
            self.write_indent();
            self.write("deny!(");
            self.write(&denied.join(", "));
            self.writeln(") {");
            self.fmt_block_body(body);
            self.write_indent();
            self.writeln("}");
        }

        Stmt::Break { .. } => {
            self.write_indent();
            self.writeln("break");
        }

        Stmt::Continue { .. } => {
            self.write_indent();
            self.writeln("continue");
        }

        Stmt::Expr { expr, .. } => {
            self.write_indent();
            self.write(&self.fmt_expr_to_string(expr));
            self.newline();
        }

        Stmt::Spawn { expr, .. } => {
            self.write_indent();
            self.write("spawn ");
            self.write(&self.fmt_expr_to_string(expr));
            self.newline();
        }

        Stmt::Select { branches, .. } => {
            self.write_indent();
            self.writeln("select {");
            self.push_indent();
            for branch in branches {
                self.write_indent();
                self.write(&branch.pattern);
                self.write(" <- ");
                self.write(&self.fmt_expr_to_string(&branch.channel));
                self.writeln(" {");
                self.fmt_block_body(&branch.body);
                self.write_indent();
                self.writeln("}");
            }
            self.pop_indent();
            self.write_indent();
            self.writeln("}");
        }

        Stmt::TryCatch {
            try_block,
            catch_name,
            catch_block,
            ..
        } => {
            self.write_indent();
            self.writeln("try {");
            self.fmt_block_body(try_block);
            self.write_indent();
            self.write("} catch ");
            self.write(catch_name);
            self.writeln(" {");
            self.fmt_block_body(catch_block);
            self.write_indent();
            self.writeln("}");
        }

        Stmt::Throw { expr, .. } => {
            self.write_indent();
            self.write("throw ");
            self.write(&self.fmt_expr_to_string(expr));
            self.newline();
        }
    }
}

// -----------------------------------------------------------------------
// Expressions (rendered to a String for inline embedding)
// -----------------------------------------------------------------------

fn fmt_expr_to_string(&self, expr: &Expr) -> String {
    match expr {
        // A NEGATIVE IntLiteral value can only come from a u64-range
        // source literal (plain literals parse from unsigned digit text;
        // `-x` is a unary-minus node). Printing it signed rewrote
        // `18446744073709551615` / `0xFFFF...` as `-1` -- which no longer
        // even compiles under E0111. Reinterpret as u64 to restore the
        // original value (hex literals normalize to decimal, same value).
        Expr::IntLiteral { value, .. } => {
            if *value < 0 {
                (*value as u64).to_string()
            } else {
                value.to_string()
            }
        }
        Expr::FloatLiteral { value, .. } => format_float(*value),
        Expr::StringLiteral { value, .. } => format!("\"{}\"", escape_string(value)),
        Expr::InterpolatedString { parts, .. } => {
            let mut s = String::from("\"");
            for part in parts {
                match part {
                    StringPart::Literal(lit) => s.push_str(&escape_string(lit)),
                    StringPart::Expr(e) => {
                        // Kryos interpolation is `{expr}`, NOT `${expr}`.
                        // Emitting `${` produced a literal `$` in the
                        // output and silently changed program behavior
                        // (`"{x}"` -> `"${x}"` prints a stray `$`).
                        s.push('{');
                        s.push_str(&self.fmt_expr_to_string(e));
                        s.push('}');
                    }
                }
            }
            s.push('"');

    s
}
Expr::CharLiteral { value, .. } => format!("'{}'", escape_char(*value)),
Expr::BoolLiteral { value, .. } => {
    if *value {
        "true".to_string()
    } else {
        "false".to_string()
    }
}
Expr::NoneLiteral { .. } => "none".to_string(),

Expr::Identifier { name, .. } => name.clone(),

Expr::FieldAccess { object, field, .. } => {
    format!("{}.{}", self.fmt_expr_to_string(object), field)
}

Expr::IndexAccess { object, index, .. } => {
    format!(
        "{}[{}]",
        self.fmt_expr_to_string(object),
        self.fmt_expr_to_string(index)
    )
}

Expr::BinaryOp {
    op, left, right, ..
} => {
    let left_str = self.maybe_paren_left(left, *op);
    let right_str = self.maybe_paren_right(right, *op);
    format!("{} {} {}", left_str, binop_str(*op), right_str)
}

Expr::UnaryOp { op, operand, .. } => {
    let op_str = match op {
        UnOp::Neg => "-",
        UnOp::Not => "not ",
        UnOp::BitNot => "~",
    };
    let inner = self.fmt_expr_to_string(operand);
    // Parenthesize binary ops inside unary to avoid ambiguity
    if matches!(**operand, Expr::BinaryOp { .. }) {
        format!("{}({})", op_str, inner)
    } else {
        format!("{}{}", op_str, inner)
    }
}

Expr::FnCall { callee, args, .. } => {
    let callee_str = self.fmt_expr_to_string(callee);
    let args_str: Vec<String> =
        args.iter().map(|a| self.fmt_expr_to_string(a)).collect();
    format!("{}({})", callee_str, args_str.join(", "))
}

Expr::MethodCall {
    object,
    method,
    args,
    ..
} => {
    let obj_str = self.fmt_expr_to_string(object);
    let args_str: Vec<String> =
        args.iter().map(|a| self.fmt_expr_to_string(a)).collect();
    format!("{}.{}({})", obj_str, method, args_str.join(", "))
}

Expr::StaticMethodCall {
    type_name,
    method,
    args,
    ..
} => {
    let args_str: Vec<String> =
        args.iter().map(|a| self.fmt_expr_to_string(a)).collect();
    format!("{}::{}({})", type_name, method, args_str.join(", "))
}

Expr::ArrayLiteral { elements, .. } => {
    let elems: Vec<String> = elements
        .iter()
        .map(|e| self.fmt_expr_to_string(e))
        .collect();
    format!("[{}]", elems.join(", "))
}

Expr::TupleLiteral { elements, .. } => {
    let elems: Vec<String> = elements
        .iter()
        .map(|e| self.fmt_expr_to_string(e))
        .collect();
    if elems.len() == 1 {
        format!("({},)", elems[0])
    } else {
        format!("({})", elems.join(", "))
    }
}

Expr::MapLiteral { entries, .. } => {
    let items: Vec<String> = entries
        .iter()
        .map(|(k, v)| {
            format!(
                "{}: {}",
                self.fmt_expr_to_string(k),
                self.fmt_expr_to_string(v)
            )
        })
        .collect();
    format!("{{{}}}", items.join(", "))
}

Expr::StructLiteral { name, fields, .. } => {
    let field_strs: Vec<String> = fields
        .iter()
        .map(|(fname, fval)| format!("{}: {}", fname, self.fmt_expr_to_string(fval)))
        .collect();
    format!("{} {{ {} }}", name, field_strs.join(", "))
}

Expr::Lambda {
    params,
    ret_ty,
    body,
    ..
} => {
    // Closures print in the bar form the language documents
    // (`|x| x * 2`), not a rewritten `fn(x) { x * 2 }` -- a
    // formatter re-lays-out code, it does not switch the
    // syntactic form the programmer chose.
    let mut s = String::from("|");
    for (i, p) in params.iter().enumerate() {
        if i > 0 {
            s.push_str(", ");
        }
        s.push_str(&self.fmt_param_to_string(p));
    }
    s.push('|');
    if let Some(ty) = ret_ty {
        s.push_str(" -> ");
        s.push_str(&self.fmt_type_to_string(ty));
    }
    s.push(' ');
    s.push_str(&self.fmt_expr_to_string(body));
    s
}

Expr::IfExpr {
    condition,
    then_branch,
    else_branch,
    ..
} => {
    let mut s = format!("if {} {{ ", self.fmt_expr_to_string(condition));
    s.push_str(&self.fmt_block_inline(then_branch));
    s.push_str(" }");
    if let Some(else_blk) = else_branch {
        s.push_str(" else { ");
        s.push_str(&self.fmt_block_inline(else_blk));
        s.push_str(" }");
    }
    s
}

Expr::MatchExpr { subject, arms, .. } => {
    // Re-sugar the parser's `?` desugaring back to `expr?`. The
    // parser expands `expr?` into a Result match binding
    // compiler-internal `__kry_try_*` temps at PARSE time, so a
    // naive AST print leaked those internals into user source
    // (and the emitted `Result::Ok(__kry_try_v_0)` block did not
    // even reparse). The desugar shape is exact and unambiguous.
    if let Some(sugared) = self.try_resugar_question(subject, arms) {
        return sugared;
    }
    let mut s = format!("match {} {{\n", self.fmt_expr_to_string(subject));
    for arm in arms {
        let indent_str = " ".repeat((self.indent + 1) * INDENT_WIDTH);
        s.push_str(&indent_str);
        s.push_str(&self.fmt_pattern_to_string(&arm.pattern));
        if let Some(guard) = &arm.guard {
            s.push_str(" if ");
            s.push_str(&self.fmt_expr_to_string(guard));
        }
        s.push_str(" => ");
        s.push_str(&self.fmt_expr_to_string(&arm.body));
        s.push('\n');
    }
    let indent_str = " ".repeat(self.indent * INDENT_WIDTH);
    s.push_str(&indent_str);
    s.push('}');
    s
}

Expr::RangeExpr {
    start,
    end,
    inclusive,
    ..
} => {
    let mut s = String::new();
    if let Some(start) = start {
        s.push_str(&self.fmt_expr_to_string(start));
    }
    if *inclusive {
        s.push_str("..=");
    } else {
        s.push_str("..");
    }
    if let Some(end) = end {
        s.push_str(&self.fmt_expr_to_string(end));
    }
    s
}

Expr::PipeExpr { left, right, .. } => {
    format!(
        "{} |> {}",
        self.fmt_expr_to_string(left),
        self.fmt_expr_to_string(right)
    )
}

Expr::Borrow {
    inner,
    mutable: true,
    ..
} => {
    format!("&mut {}", self.fmt_expr_to_string(inner))
}
Expr::Borrow {
    inner,
    mutable: false,
    ..
} => {
    format!("&{}", self.fmt_expr_to_string(inner))
}
Expr::Deref { inner, .. } => {
    format!("*{}", self.fmt_expr_to_string(inner))
}

Expr::SharedExpr { inner, .. } => {
    format!("shared {}", self.fmt_expr_to_string(inner))
}
Expr::MoveExpr { inner, .. } => {
    format!("move {}", self.fmt_expr_to_string(inner))
}
Expr::WeakExpr { inner, .. } => {
    format!("weak {}", self.fmt_expr_to_string(inner))
}

Expr::ComptimeBlock { body, .. } => {
    let mut s = String::from("comptime {\n");
    s.push_str(&self.fmt_block_as_string(body));
    let indent_str = " ".repeat(self.indent * INDENT_WIDTH);
    s.push_str(&indent_str);
    s.push('}');
    s
}

Expr::UnsafeBlock { body, .. } => {
    let mut s = String::from("unsafe {\n");
    s.push_str(&self.fmt_block_as_string(body));
    let indent_str = " ".repeat(self.indent * INDENT_WIDTH);
    s.push_str(&indent_str);
    s.push('}');
    s
}

Expr::QuantumBlock { body, .. } => {
    let mut s = String::from("quantum {\n");
    s.push_str(&self.fmt_block_as_string(body));
    let indent_str = " ".repeat(self.indent * INDENT_WIDTH);
    s.push_str(&indent_str);
    s.push('}');
    s
}

Expr::Cast { expr, ty, .. } => {
    // `as` binds TIGHTER than binary operators and a leading unary
    // `-` (gotcha #18), so the cast operand must keep its parens
    // when it is a looser-binding expression. Emitting
    // `(x + y) as f64` as `x + y as f64` re-parses as
    // `x + (y as f64)` -- a DIFFERENT AST that no longer compiles
    // (dropping semantically-required parens is a formatter bug).
    let needs_parens = matches!(
        expr.as_ref(),
        Expr::BinaryOp { .. }
            | Expr::UnaryOp { .. }
            | Expr::IfExpr { .. }
            | Expr::MatchExpr { .. }
            | Expr::RangeExpr { .. }
            | Expr::PipeExpr { .. }
            | Expr::Cast { .. }
    );
    let inner = self.fmt_expr_to_string(expr);
    if needs_parens {
        format!("({}) as {}", inner, self.fmt_type_to_string(ty))
    } else {
        format!("{} as {}", inner, self.fmt_type_to_string(ty))

            }
        }

        Expr::Block { block, .. } => {
            let mut s = String::from("{\n");
            s.push_str(&self.fmt_block_as_string(block));
            let indent_str = " ".repeat(self.indent * INDENT_WIDTH);
            s.push_str(&indent_str);
            s.push('}');
            s
        }

        Expr::Await { value, .. } => {
            format!("await {}", self.fmt_expr_to_string(value))
        }
    }
}

/// Format a block's statements as a string (for inline use in expressions).
fn fmt_block_inline(&self, block: &Block) -> String {
    let stmts: Vec<String> = block
        .stmts
        .iter()
        .map(|s| self.fmt_stmt_to_string(s))
        .collect();
    stmts.join("; ")
}

/// Format a block with proper indentation as a string.
fn fmt_block_as_string(&self, block: &Block) -> String {
    let mut s = String::new();
    let indent_str = " ".repeat((self.indent + 1) * INDENT_WIDTH);
    for stmt in &block.stmts {
        s.push_str(&indent_str);
        s.push_str(&self.fmt_stmt_to_string(stmt));
        s.push('\n');
    }
    s
}

/// Format a single statement to string (no leading indent, no trailing newline).
fn fmt_stmt_to_string(&self, stmt: &Stmt) -> String {
    match stmt {
        Stmt::Let {
            name,
            mutable,
            ty,
            value,
            pattern,
            ..
        } => {
            let mut s = String::from("let ");
            if *mutable {
                s.push_str("mut ");
            }
            if let Some(pat) = pattern {
                s.push_str(&self.fmt_pattern_to_string(pat));
            } else {
                s.push_str(name);
            }
            if let Some(ty) = ty {
                s.push_str(": ");
                s.push_str(&self.fmt_type_to_string(ty));
            }
            if let Some(val) = value {
                s.push_str(" = ");
                s.push_str(&self.fmt_expr_to_string(val));
            }
            s
        }
        Stmt::Return { value, .. } => {
            let mut s = String::from("return");
            if let Some(val) = value {
                s.push(' ');
                s.push_str(&self.fmt_expr_to_string(val));
            }
            s
        }
        Stmt::Expr { expr, .. } => self.fmt_expr_to_string(expr),
        Stmt::Break { .. } => "break".to_string(),
        Stmt::Continue { .. } => "continue".to_string(),
        // Assignment inside an inline block (a closure body, an inline
        // if-branch). MUST be rendered -- the old `_ => "/* stmt */"`
        // fallback SILENTLY DELETED it, so `|| { c = c + 1  c }` formatted
        // to `|| { /* stmt */  c }`, a working closure turned into one that
        // never mutates.
        Stmt::Assign {
            target, op, value, ..
        } => {
            let op_str = match op {
                AssignOp::Assign => "=",
                AssignOp::AddAssign => "+=",
                AssignOp::SubAssign => "-=",
                AssignOp::MulAssign => "*=",
                AssignOp::DivAssign => "/=",
                AssignOp::ModAssign => "%=",
            };
            format!(
                "{} {} {}",
                self.fmt_expr_to_string(target),
                op_str,
                self.fmt_expr_to_string(value)
            )
        }
        Stmt::Throw { expr, .. } => {
            format!("throw {}", self.fmt_expr_to_string(expr))
        }
        Stmt::Spawn { expr, .. } => {
            format!("spawn {}", self.fmt_expr_to_string(expr))
        }
        Stmt::If {
            condition,
            then_block,
            elif_clauses,
            else_block,
            ..
        } => {
            let mut s = format!(
                "if {} {{ {} }}",
                self.fmt_expr_to_string(condition),
                self.fmt_block_inline(then_block)
            );
            for (cond, block) in elif_clauses {
                s.push_str(&format!(
                    " elif {} {{ {} }}",
                    self.fmt_expr_to_string(cond),
                    self.fmt_block_inline(block)
                ));
            }
            if let Some(else_blk) = else_block {
                s.push_str(&format!(" else {{ {} }}", self.fmt_block_inline(else_blk)));
            }
            s
        }
        Stmt::For {
            parallel,
            pattern,
            iterable,
            body,
            ..
        } => {
            format!(
                "{}for {} in {} {{ {} }}",
                if *parallel { "parallel " } else { "" },
                self.fmt_pattern_to_string(pattern),
                self.fmt_expr_to_string(iterable),
                self.fmt_block_inline(body)
            )
        }
        Stmt::While {
            condition, body, ..
        } => {
            format!(
                "while {} {{ {} }}",
                self.fmt_expr_to_string(condition),
                self.fmt_block_inline(body)
            )
        }
        Stmt::TryCatch {
            try_block,
            catch_name,
            catch_block,
            ..
        } => {
            format!(
                "try {{ {} }} catch {} {{ {} }}",
                self.fmt_block_inline(try_block),
                catch_name,
                self.fmt_block_inline(catch_block)
            )
        }
        Stmt::DenyBlock { denied, body, .. } => {
            format!(
                "deny!({}) {{ {} }}",
                denied.join(", "),
                self.fmt_block_inline(body)
            )
        }
        Stmt::Select { branches, .. } => {
            let mut s = String::from("select { ");
            for branch in branches {
                s.push_str(&format!(
                    "{} <- {} {{ {} }} ",
                    branch.pattern,
                    self.fmt_expr_to_string(&branch.channel),
                    self.fmt_block_inline(&branch.body)
                ));
            }
            s.push('}');
            s
        }
    }
}

// -----------------------------------------------------------------------
// Operator precedence for parenthesization
// -----------------------------------------------------------------------

fn binop_precedence(op: BinOp) -> u8 {
    match op {
        BinOp::Pipe => 1,
        BinOp::Or => 2,
        BinOp::And => 3,
        BinOp::Eq | BinOp::Neq | BinOp::Lt | BinOp::Gt | BinOp::LtEq | BinOp::GtEq => 4,
        BinOp::BitOr => 5,
        BinOp::BitXor => 6,
        BinOp::BitAnd => 7,
        BinOp::Shl | BinOp::Shr => 8,
        BinOp::Add | BinOp::Sub => 9,
        BinOp::Mul | BinOp::Div | BinOp::Mod | BinOp::MatMul => 10,
        BinOp::Pow => 11,
    }
}

fn maybe_paren_left(&self, expr: &Expr, parent_op: BinOp) -> String {
    let inner = self.fmt_expr_to_string(expr);
    if let Expr::BinaryOp { op, .. } = expr {
        if Self::binop_precedence(*op) < Self::binop_precedence(parent_op) {
            return format!("({})", inner);
        }
    }
    inner
}

fn maybe_paren_right(&self, expr: &Expr, parent_op: BinOp) -> String {
    let inner = self.fmt_expr_to_string(expr);
    if let Expr::BinaryOp { op, .. } = expr {
        let child_prec = Self::binop_precedence(*op);
        let parent_prec = Self::binop_precedence(parent_op);
        // Parenthesize if child is lower precedence, OR same precedence
        // for left-associative ops (to disambiguate).
        // Pow is right-associative, so skip same-precedence parens for pow-on-right.
        if child_prec < parent_prec {
            return format!("({})", inner);
        }
        if child_prec == parent_prec && parent_op != BinOp::Pow {
            return format!("({})", inner);
        }
    }
    inner
}

// -----------------------------------------------------------------------
// Type expressions
// -----------------------------------------------------------------------

fn fmt_type_to_string(&self, ty: &TypeExpr) -> String {
    match ty {
        TypeExpr::Simple { name, .. } => name.clone(),

        TypeExpr::Generic { name, args, .. } => {
            let args_str: Vec<String> =
                args.iter().map(|a| self.fmt_type_to_string(a)).collect();
            format!("{}<{}>", name, args_str.join(", "))
        }

        TypeExpr::Array { element, size, .. } => {
            let elem = self.fmt_type_to_string(element);
            if let Some(sz) = size {
                format!("[{}; {}]", elem, sz)
            } else {
                format!("[{}]", elem)
            }
        }

        TypeExpr::Tuple { elements, .. } => {
            let elems: Vec<String> = elements
                .iter()
                .map(|e| self.fmt_type_to_string(e))
                .collect();
            format!("({})", elems.join(", "))
        }

        TypeExpr::Function { params, ret, .. } => {
            let params_str: Vec<String> =
                params.iter().map(|p| self.fmt_type_to_string(p)).collect();
            format!(
                "fn({}) -> {}",
                params_str.join(", "),
                self.fmt_type_to_string(ret)
            )
        }

        TypeExpr::Optional { inner, .. } => {
            format!("{}?", self.fmt_type_to_string(inner))
        }

        TypeExpr::Reference { inner, mutable, .. } => {
            if *mutable {
                format!("&mut {}", self.fmt_type_to_string(inner))
            } else {
                format!("&{}", self.fmt_type_to_string(inner))
            }
        }

        TypeExpr::Shared { inner, .. } => {
            format!("shared {}", self.fmt_type_to_string(inner))
        }

        TypeExpr::Weak { inner, .. } => {

                format!("weak {}", self.fmt_type_to_string(inner))
            }

            TypeExpr::Pointer { inner, mutable, .. } => {
                if *mutable {
                    format!("*mut {}", self.fmt_type_to_string(inner))
                } else {
                    format!("*{}", self.fmt_type_to_string(inner))
                }
            }

            TypeExpr::DynTrait { trait_name, .. } => format!("dyn {trait_name}"),

            TypeExpr::Inferred { .. } => "_".to_string(),
        }
    }

    // -----------------------------------------------------------------------
    // Patterns
    // -----------------------------------------------------------------------

    /// Detect the parser's `?` desugaring and return the `expr?` surface
    /// form: exactly two guardless arms, `Result::Ok(__kry_try_v_N)` whose
    /// body is that same binding, and `Result::Err(__kry_try_e_N)`. The
    /// `__kry_try_` prefix is reserved for the desugar (parser fresh_name),
    /// so user code can never collide with this shape.
    fn try_resugar_question(&self, subject: &Expr, arms: &[MatchArm]) -> Option<String> {
        if arms.len() != 2 {
            return None;
        }
        let ok_arm = &arms[0];
        let err_arm = &arms[1];
        if ok_arm.guard.is_some() || err_arm.guard.is_some() {
            return None;
        }
        let ok_binding = match &ok_arm.pattern {
            Pattern::Enum {
                name,
                variant,
                fields,
                ..
            } if name == "Result" && variant == "Ok" && fields.len() == 1 => match &fields[0] {
                Pattern::Ident { name, .. } if name.starts_with("__kry_try_") => name.clone(),
                _ => return None,
            },
            _ => return None,
        };
        match ok_arm.body.as_ref() {
            Expr::Identifier { name, .. } if *name == ok_binding => {}
            _ => return None,
        }
        let err_matches = match &err_arm.pattern {
            Pattern::Enum {
                name,
                variant,
                fields,
                ..
            } if name == "Result" && variant == "Err" && fields.len() == 1 => {
                matches!(&fields[0], Pattern::Ident { name, .. } if name.starts_with("__kry_try_"))
            }
            _ => false,
        };
        if !err_matches {
            return None;
        }
        Some(format!("{}?", self.fmt_expr_to_string(subject)))
    }

    fn fmt_pattern_to_string(&self, pattern: &Pattern) -> String {
        match pattern {
            Pattern::Wildcard { .. } => "_".to_string(),

            Pattern::Ident { name, mutable, .. } => {
                if *mutable {
                    format!("mut {}", name)
                } else {
                    name.clone()
                }
            }

            Pattern::Literal { expr, .. } => self.fmt_expr_to_string(expr),

            Pattern::Tuple { elements, .. } => {
                let elems: Vec<String> = elements
                    .iter()
                    .map(|e| self.fmt_pattern_to_string(e))
                    .collect();
                format!("({})", elems.join(", "))
            }

            Pattern::Struct { name, fields, .. } => {
                let fields_str: Vec<String> = fields
                    .iter()
                    .map(|(fname, fpat)| {
                        let pat_str = self.fmt_pattern_to_string(fpat);
                        if fname == &pat_str {
                            fname.clone()
                        } else {
                            format!("{}: {}", fname, pat_str)
                        }
                    })
                    .collect();
                format!("{} {{ {} }}", name, fields_str.join(", "))
            }

            Pattern::Enum {
                name,
                variant,
                fields,
                ..
            } => {
                // A BARE variant pattern (`Circle(r)` inside a match whose
                // subject type supplies the enum) parses with an EMPTY enum
                // name. Printing the qualified form unconditionally produced
                // a dangling `::Circle(r)` -- which does not parse, so fmt
                // turned compiling programs into permanently broken ones.
                let qualifier = if name.is_empty() {
                    String::new()
                } else {
                    format!("{}::", name)
                };
                if fields.is_empty() {
                    format!("{}{}", qualifier, variant)
                } else {
                    let fields_str: Vec<String> = fields
                        .iter()
                        .map(|f| self.fmt_pattern_to_string(f))
                        .collect();
                    format!("{}{}({})", qualifier, variant, fields_str.join(", "))
                }
            }

            Pattern::Or { patterns, .. } => {
                let parts: Vec<String> = patterns
                    .iter()
                    .map(|p| self.fmt_pattern_to_string(p))
                    .collect();
                parts.join(" | ")
            }
        }
    }
}

